/* FAQ (mirrors docs/FAQ.md), grouped into sections. Each answer `a` is a list of blocks:
   a string = paragraph, an array = bullet list, { table: [[header…], [row…], …] } = table. `code` in backticks. */
window.FAQ = {
  tr: [
    { section: 'Genel', items: [
      { id: 'nosound', q: 'Şarkı bulunuyor ama ses gelmiyor / logda "Song queue ended" yazıyor',
        a: ['Kayıtlar sayfasındaki sarı/kırmızı satırlara bak. Genelde sebep YouTube\'un engellemesidir: Ayarlar → "yt-dlp güncelle", olmazsa YouTube çerezi yükle (aşağıda). Bot TeamSpeak\'e bağlı değilse (panelde "Bağlanıyor") ses gitmez.'] },
      { id: 'cookies', q: 'Logda "YouTube bot doğrulaması istedi / Sign in to confirm you\'re not a bot"',
        a: ['Sunucunun IP\'si YouTube tarafından engelleniyor. Kendi bilgisayarında tarayıcıya `Get cookies.txt LOCALLY` eklentisini kur, YouTube\'a giriş yapmışken youtube.com için `cookies.txt` dosyasını dışa aktar ve Ayarlar → YouTube çerezleri → "cookies.txt yükle" ile yükle. Mümkünse ayrı (ikincil) bir Google hesabı kullan.'] },
      { id: 'ytdlp', q: 'YouTube bir anda çalmayı bıraktı',
        a: ['YouTube sık değişir. Ayarlar → "yt-dlp güncelle".'] },
      { id: 'dupname', q: 'Bot sunucuda "Frix1" olarak görünüyor',
        a: ['Sunucuda aynı isimde başka bir istemci var (eski bot, ya da bot kapanmadan yeniden bağlandı). Diğerini kapat; bot bir sonraki bağlantıda asıl adını alır.'] },
      { id: 'radio', q: 'Radyo çalmıyor',
        a: ['Doğrudan yayın adresi (`.mp3`, `.aac`, Icecast/Shoutcast) ya da `.m3u`, `.pls`, `.m3u8` linki kullan. Linki önce VLC\'de dene. Web sayfası linkleri (ör. radyonun ana sayfası) çalışmaz.'] },
      { id: 'live', q: 'Canlı yayın çalınabilir mi?',
        a: ['Evet: YouTube canlı yayınları, Twitch ve internet radyoları desteklenir. Canlı yayınlarda ileri sarma yoktur (çalarda CANLI etiketi görünür).'] },
      { id: 'roles', q: 'Roller ne demek?',
        a: [['Yönetici: her şey.', 'DJ: şarkı/radyo ekleme ve oynatıcı kontrolü.', 'İzleyici: sadece durumu görür.']] },
      { id: 'multibot', q: 'Birden fazla bot nasıl çalıştırılır?',
        a: ['Botlar → "Yeni bot". Örneğin bir müzik botu ve sadece karşılama/duyuru eklentileri açık bir karşılama botu oluşturabilirsin. Her bot ayrı bir TeamSpeak istemcisi olarak bağlanır.'] },
    ] },
    { section: 'Eklentiler', items: [
      { id: 'plugins', q: 'Eklentiler nasıl ayarlanır, hangi yetkiler gerekir?',
        a: ['Eklentiler her bot için ayrı ayrı açılır: Eklentiler → bot seç → kartı aç → ayarla → Kaydet. Kanal alanlarına kanalın adını ya da ID\'sini (`5` veya `/5`) yazabilirsin. Grup alanlarına sunucu grubu ID\'lerini virgülle yaz (TeamSpeak\'te İzinler → Sunucu Grupları penceresinde görünür).', { table: [
            ['Eklenti', 'Ne yapar', 'Botun TeamSpeak\'te ihtiyacı olan yetki'],
            ['Karşılama mesajı', 'Sunucuya bağlanana / botun kanalına girene özel mesaj, dürtme ya da kanal mesajı gönderir', '— (dürtme için `i_client_poke_power`)'],
            ['Duyuru / Reklam', 'Belirli aralıklarla kanala ya da sunucuya mesaj atar (sıralı veya rastgele)', 'Sunucu mesajı için `b_client_server_textmessage_send`'],
            ['Yalnızken duraklat', 'Botun kanalında kimse kalmayınca müziği duraklatır, biri gelince devam eder', '—'],
            ['Boştayken radyo', 'Kuyruk bitip bot bir süre boş kalınca seçilen radyoyu çalar', '—'],
            ['AFK taşıyıcı', 'Boşta kalan, "uzakta" olan ya da hoparlörü kapalı olanları AFK kanalına taşır, dönünce geri alır', '`i_client_move_power` (taşınacak kişilerin `i_client_needed_move_power` değerinden yüksek)'],
            ['İsim filtresi', 'Takma adında yasaklı kelime geçenleri uyarır ya da sunucudan atar', 'Atmak için `i_client_kick_from_server_power`'],
            ['Destek bildirimi', 'Destek kanalına biri girince yetkili gruplardaki çevrimiçi kişilere dürtme gönderir, kişiye bilgi verir', '`i_client_poke_power`'],
            ['Kanal adında bilgi', 'Seçilen kanalın adını çevrimiçi sayısı ve saatle günceller', '`b_channel_modify_name` (o kanalda)']] }] },
      { id: 'afk', q: 'AFK taşıyıcı kimseyi taşımıyor',
        a: [['"AFK kanalı" alanındaki ad sunucudaki kanal adıyla birebir aynı olmalı (ya da ID yaz). Bulunamazsa Kayıtlar sayfasında "kanal bulunamadı" uyarısı çıkar.', 'Botun taşıma gücü, taşınacak kişininkinden yüksek olmalı. Sunucu yöneticilerini taşıyamaz; onları "Hariç tutulan gruplar" alanına yazmak da iyi olur.', 'Kontrol 30 saniyede bir yapılır, yani taşıma birkaç saniye gecikebilir.']] },
      { id: 'namefilter', q: 'İsim filtresi yanlış kişileri yakalıyor',
        a: ['Kelime takma adın herhangi bir yerinde geçerse eşleşir (büyük/küçük harf fark etmez). Çok kısa kelimelerden kaçın, istisna grupları "Hariç tutulan gruplar" alanına ekle. Önce "dürt" ile dene, emin olunca "at"a geç.'] },
      { id: 'support', q: 'Destek bildirimi kimseye gitmiyor',
        a: ['"Yetkili grup ID\'leri" boşsa ya da o gruplardan kimse çevrimiçi değilse kişiye "yetkili yok" mesajı gider. Aynı kişi için bekleme süresi (varsayılan 5 dk) dolmadan tekrar bildirim gitmez.'] },
      { id: 'channelinfo', q: 'Kanal adı değişmiyor',
        a: ['Botun o kanalda adı düzenleme yetkisi olmalı (Kayıtlar\'da "Kanal adı değiştirilemedi" uyarısı çıkar). Kanal adları en fazla 40 karakter olabilir, şablon uzunsa kesilir. Adı değişeceği için kanalı mümkünse ID ile seç.'] },
      { id: 'welcome', q: 'Karşılama mesajı bot açılınca herkese gidiyor mu?',
        a: ['Hayır. Bot bağlandıktan sonraki ilk 15 saniyedeki girişler (zaten sunucuda olanlar) yok sayılır ve aynı kişiye "tekrar" süresi dolmadan ikinci kez gönderilmez.'] },
    ] },
    { section: 'Yeni eklentiler', items: [
      { id: 'newplugins', q: 'Yeni eklentiler ne yapar, hangi yetkiler gerekir?',
        a: ['Hepsi Eklentiler sayfasında, her bot için ayrı açılır. "Eğlence ve araçlar" varsayılan olarak açıktır.', { table: [
            ['Eklenti', 'Ne yapar', 'Komut', 'Botun ihtiyacı olan yetki'],
            ['Kayıt botu', 'Kayıt kanalına giren kayıtsızları yetkililere dürter; yetkili kaydedince üye grubunu verir, kayıtsız grubunu kaldırır, lobiye taşır', '`!register <isim>` (`!kayit`) (sadece yetkili gruplar)', '`i_group_member_add_power`, `i_group_member_remove_power`, `i_client_move_power`, `i_client_poke_power`'],
            ['Geçici kanal oluşturucu', '"Kanal oluştur" kanalına girene kendi adıyla geçici kanal açar ve taşır; kanal boşalınca TeamSpeak siler', '—', '`b_channel_create_temporary`, `i_client_move_power`'],
            ['Aktiflik rütbeleri', 'Sunucuda geçirilen süreyi sayar, `10=12` gibi tanımlanan saatlere ulaşana grup verir', '`!time` (`!sure`), `!top`', '`i_group_member_add_power` (ve önceki rütbeyi kaldırmak için `..._remove_power`)'],
            ['Kanal koruma', 'Korunan kanala izinli grup dışından gireni dışarı taşır ya da kanaldan atar', '—', '`i_client_move_power` veya `i_client_kick_from_channel_power`'],
            ['Flood koruması', 'Kısa sürede çok mesaj atanı dürterek uyarır, tekrarlarsa kanaldan/sunucudan atar', '—', 'atma yetkileri, `i_client_poke_power`'],
            ['Oylamayla geç', '`!next` (`!gec`) hemen geçmez; kanaldakilerin belirli oranı oy verince geçer (şarkıyı açan ve muaf gruplar direkt geçer)', '`!next` (`!gec`)', '—'],
            ['DJ yetkisi ve kuyruk limiti', 'Şarkı eklemeyi DJ gruplarına sınırlar, kişi başına kuyruk sınırı koyar; istenirse geç/dur/ses/bitir de sadece DJ\'ler', '—', '—'],
            ['Zamanlı duyuru', '`21:00 | mesaj` ya da `Cmt,Paz 12:00 | mesaj` satırlarıyla belirli gün/saatte mesaj atar', '—', 'sunucu mesajı için `b_client_server_textmessage_send`'],
            ['Eğlence ve araçlar (varsayılan açık)', 'Zar, yazı-tura, seçim, anket, hava durumu, döviz, şarkı sözleri; istemediğin komutu kapatabilirsin', '`!dice` (`!zar`), `!coin` (`!yazitura`), `!pick` (`!sec`), `!poll` (`!anket`), `!vote` (`!oy`), `!weather` (`!hava`), `!fx` (`!doviz`), `!usd` (`!dolar`), `!eur` (`!euro`), `!lyrics` (`!soz`)', '—']] }] },
      { id: 'newcmds', q: 'Yeni komutlar nasıl kullanılır?',
        a: [['`!register Ahmet` (`!kayit`) — kayıt kanalındaki Ahmet\'i kaydeder. Birden fazla kişi eşleşirse bot isimleri listeler; tam adı yaz.', '`!playlist save rock` (`!liste`) (kuyruğu kaydet) · `!playlist play rock` · `!playlist add rock` (çalan şarkıyı ekle) · `!playlist show rock` · `!playlist delete rock` · `!playlist` (tüm listeler). Listeler panelde Listeler sayfasında da görünür.', '`!poll Bu akşam ne oynayalım? | CS2 | LoL | Valorant` (`!anket`) → herkes `!vote 2` (`!oy`) yazar; süre dolunca (varsayılan 2 dk) ya da `!poll end` ile sonuç kanala yazılır.', '`!weather istanbul` (`!hava`) · `!fx EUR 50` (`!doviz`) · `!usd` (`!dolar`) · `!eur 20` (`!euro`) · `!dice 2d6` (`!zar`) · `!coin` (`!yazitura`) · `!pick pizza | döner | lahmacun` (`!sec`)', '`!lyrics` (`!soz`) çalan şarkının sözlerini özel mesajla gönderir; `!lyrics tarkan kuzu kuzu` ile başka şarkı aranabilir.', '`!stats` (`!istatistik`) son 30 günün en çok çalınan şarkılarını ve en çok şarkı açanlarını gösterir; panelde İstatistik sayfasında daha fazlası var. `!time` (`!sure`) kendi süreni, `!top` en aktifleri gösterir.']] },
      { id: 'ranks', q: 'Aktiflik rütbeleri süre saymıyor / !top boş',
        a: ['Eklenti açık olmalı ve sadece bir botta açılmalı (iki botta açılırsa süre iki kez sayılır). Süre dakikada bir eklenir. Rütbeler `saat=grupID` biçiminde, her satıra bir tane yazılır.'] },
      { id: 'tempchannel', q: 'Geçici kanal açılmıyor',
        a: ['Botun geçici kanal oluşturma ve taşıma yetkisi olmalı; Kayıtlar sayfasında "Geçici kanal açılamadı" uyarısı sebebi yazar. Aynı kişi için 30 saniyede bir kanal açılır.'] },
      { id: 'services', q: 'Hava, döviz ve söz servisleri hangileri?',
        a: ['Ücretsiz ve anahtarsız servisler: open-meteo.com (hava), open.er-api.com (döviz), lrclib.net (şarkı sözleri). Bu servislere sadece şehir adı, döviz kodu ya da şarkı adı gider; kullanıcı bilgisi gitmez. Sonuçlar kısa süre önbellekte tutulur.'] },
    ] },
    { section: 'Komutlar & dil', items: [
      { id: 'rename', q: '!play (!ara), !next (!gec) gibi komutların adını değiştirebilir miyim?',
        a: ['Evet: Komutlar → "Hazır komutlar". Yeni adı yaz (ör. `ara` → `cal`) ve kaydet. "Eski ad da çalışsın" işaretini kaldırırsan eski ad kapanır. Bot cevaplarındaki, yardım metnindeki ve avatardaki komut adları kendiliğinden yeni adı gösterir.'] },
      { id: 'custom', q: 'Kendi komutumu nasıl eklerim?',
        a: ['Komutlar → "Özel komutlar". Metin türü sabit bir cevap verir (ör. `!discord` → davet linki; `{user}`, `{args}`, `{time}`, `{date}` kullanılabilir). Kısayol (yönlendirme) türü başka bir komutu çalıştırır (ör. `!sarki` → `!play` (`!ara`)). Özel komut adı hazır bir komutla aynı olamaz.'] },
      { id: 'avatar', q: 'Botun avatarı neden komut listesi gösteriyor?',
        a: ['Bot boştayken avatarı, ayarladığın komutlara göre otomatik çizilir (yeniden adlandırılan komutlar, özel komutlar ve radyo varsa `!radio` (`!radyo`)). Açıklamaları Komutlar → "Bot metinleri" bölümündeki `avatar.*` satırlarından değiştirebilirsin. Şarkı çalarken avatar şarkının kapağı olur. Tamamen kendi resmini kullanmak istersen `bots/<bot-adı>/avatars/` klasörüne `sleep.png` koy.'] },
      { id: 'lang', q: 'Botun cevapları başka dilde olsun',
        a: ['Ayarlar → "TeamSpeak cevap dili": Türkçe, English, Deutsch, Español, Français, Русский, Português, Polski, Italiano. Tek tek cevapları Komutlar → "Bot metinleri" bölümünden düzenleyebilirsin. Hazır komutların adlarını da bir dile göre ayarlamak için Komutlar → "Komut adlarını bu dile göre ayarla"yı kullan (kurulumda seçilen dile göre otomatik ayarlanır; Türkçe adlar her zaman çalışır).'] },
    ] },
    { section: 'Kurulum', items: [
      { id: 'rights', q: '"You are missing the \'cmd.xxx\' right" hatası',
        a: ['Bot klasöründeki `rights.toml` dosyasında ilgili komutu en üstteki `"+" = [ ... ]` listesine ekle ve botu yeniden başlat. (Web panel kullanıcıları bu dosyadan etkilenmez.)'] },
      { id: 'commander', q: 'Channel commander açılmıyor',
        a: ['Botun sunucu grubunda `b_client_use_channel_commander` yetkisi olmalı. Logda uyarı yazar.'] },
      { id: 'connect', q: 'Bot sunucuya bağlanamıyor',
        a: ['Adresi `ip:port` olarak gir (varsayılan port 9987), sunucu şifresi varsa bot ayarlarına yaz. İlk bağlantıda sunucu "güvenlik seviyesi" isteyebilir; bot bunu otomatik hesaplar, 10-60 sn sürebilir. Logda sebep yazar.'] },
      { id: 'firewall', q: 'Panele dışarıdan ulaşamıyorum',
        a: ['Güvenlik duvarında TCP 58913 portunu aç (Windows Güvenlik Duvarı / `ufw allow 58913/tcp`). Bulut sağlayıcının (AWS, Hetzner…) ağ kurallarını da kontrol et. İlk kurulum dışarıdan yapılıyorsa kurulum kodu istenir (`KURULUM_KODU.txt`).'] },
      { id: 'forgot', q: 'Yönetici şifremi unuttum',
        a: ['Başka bir yönetici Kullanıcılar sayfasından şifreni sıfırlayabilir. Hiç yönetici kalmadıysa botu kapat, `frix.db` dosyasını sil ve yeniden başlat (radyolar, komutlar ve eklenti ayarları da sıfırlanır; botlar ve TeamSpeak ayarları kalır).'] },
      { id: 'linux', q: 'Linux\'ta ses yok / "libopus" hatası',
        a: ['`sudo apt install libopus0 ffmpeg` (Debian/Ubuntu). `install.sh` bunları otomatik kurar. Program `/opt/frix` altında kuruluysa durumu `systemctl status frix`, canlı kayıtları `journalctl -u frix -f` ile görebilirsin.'] },
      { id: 'autostart', q: 'Bilgisayar açılınca otomatik başlasın',
        a: ['Windows: `Frix.exe` tepsi simgesi → "Windows açılışında başlat" (varsayılan açık). Linux: `install.sh` systemd servisini açar (`systemctl enable frix`).'] },
    ] },
  ],
  en: [
    { section: 'General', items: [
      { id: 'nosound', q: 'A song is found but there is no sound / "Song queue ended" in the log',
        a: ['Check the yellow/red lines on the Logs page. Usually YouTube is blocking: Settings → "Update yt-dlp"; if that doesn\'t help, upload YouTube cookies (below). If the bot is not connected to TeamSpeak ("connecting"), no audio is sent.'] },
      { id: 'cookies', q: '"Sign in to confirm you\'re not a bot" in the log',
        a: ['YouTube blocks the server IP. Install the `Get cookies.txt LOCALLY` browser extension, export `cookies.txt` for youtube.com while logged in, and upload it in Settings → YouTube cookies → "Upload cookies.txt". Preferably use a secondary Google account.'] },
      { id: 'ytdlp', q: 'YouTube suddenly stopped working',
        a: ['YouTube changes often. Settings → "Update yt-dlp".'] },
      { id: 'dupname', q: 'The bot appears as "Frix1"',
        a: ['Another client with the same nickname is on the server (an old bot, or a reconnect before the old session timed out). Close the other one; the bot gets its name back on the next connect.'] },
      { id: 'radio', q: 'A radio station doesn\'t play',
        a: ['Use a direct stream URL (`.mp3`, `.aac`, Icecast/Shoutcast) or a `.m3u`, `.pls`, `.m3u8` link. Test it in VLC first. Web page URLs don\'t work.'] },
      { id: 'live', q: 'Can it play live streams?',
        a: ['Yes: YouTube live, Twitch and internet radio. Seeking is not available for live streams (the player shows a LIVE tag).'] },
      { id: 'roles', q: 'What do the roles mean?',
        a: [['Admin: everything.', 'DJ: add songs/radios and control playback.', 'Viewer: read-only.']] },
      { id: 'multibot', q: 'How do I run multiple bots?',
        a: ['Bots → "New bot" — e.g. a music bot plus a welcome bot that only has the welcome/announcement plugins enabled. Each bot connects as its own TeamSpeak client.'] },
    ] },
    { section: 'Plugins', items: [
      { id: 'plugins', q: 'How are plugins configured and which permissions do they need?',
        a: ['Plugins are enabled per bot: Plugins → pick a bot → expand the card → configure → Save. Channel fields accept the channel name or ID (`5` or `/5`). Group fields take comma-separated server group IDs (shown in TeamSpeak under Permissions → Server Groups).', { table: [
            ['Plugin', 'What it does', 'Permission the bot needs'],
            ['Welcome message', 'Private message, poke or channel message for users who connect / join the bot\'s channel', '— (poke: `i_client_poke_power`)'],
            ['Announcements / Ads', 'Posts messages to the channel or server at intervals (sequential or random)', 'Server messages: `b_client_server_textmessage_send`'],
            ['Pause when alone', 'Pauses when nobody is left in the bot\'s channel, resumes when someone joins', '—'],
            ['Idle radio', 'Plays a chosen radio station when the queue has been empty for a while', '—'],
            ['AFK mover', 'Moves idle, away or speaker-muted users to an AFK channel and back when they return', '`i_client_move_power` (higher than the target\'s `i_client_needed_move_power`)'],
            ['Nickname filter', 'Warns or kicks users whose nickname contains a forbidden word', 'Kick: `i_client_kick_from_server_power`'],
            ['Support notifier', 'Pokes online staff when someone joins the support channel and informs the user', '`i_client_poke_power`'],
            ['Channel name info', 'Keeps a channel name updated with the online count and time', '`b_channel_modify_name` (on that channel)']] }] },
      { id: 'afk', q: 'The AFK mover doesn\'t move anyone',
        a: [['The "AFK channel" must match the channel name exactly (or use its ID). If it can\'t be found, a "channel not found" warning appears in Logs.', 'The bot\'s move power must be higher than the user\'s. It can\'t move server admins; also add them to "Excluded groups".', 'Checks run every 30 seconds, so a move can be delayed a little.']] },
      { id: 'namefilter', q: 'The nickname filter catches the wrong people',
        a: ['A word matches anywhere in the nickname (case-insensitive). Avoid very short words and add exempt groups to "Excluded groups". Start with "poke", switch to "kick" once you\'re sure.'] },
      { id: 'support', q: 'The support notifier doesn\'t notify anyone',
        a: ['If "Staff group IDs" is empty or nobody from those groups is online, the user gets the "no staff" message. The same user is not notified again until the cooldown (default 5 min) has passed.'] },
      { id: 'channelinfo', q: 'The channel name doesn\'t change',
        a: ['The bot needs permission to edit that channel\'s name (a "could not change channel name" warning appears in Logs). Channel names are limited to 40 characters; longer templates are cut. Since the name changes, prefer selecting the channel by ID.'] },
      { id: 'welcome', q: 'Does the welcome message go to everyone when the bot starts?',
        a: ['No. Joins during the first 15 seconds after the bot connects (people who were already online) are ignored, and the same user isn\'t greeted again before the "repeat" time.'] },
    ] },
    { section: 'New plugins', items: [
      { id: 'newplugins', q: 'What do the new plugins do and which permissions do they need?',
        a: ['All of them are enabled per bot on the Plugins page. "Fun & tools" is on by default.', { table: [
            ['Plugin', 'What it does', 'Command', 'Permission the bot needs'],
            ['Registration', 'Pokes staff when an unregistered user joins the registration channel; staff registration grants the member group, removes the unregistered group and moves the user to the lobby', '`!register <name>` (staff groups only)', '`i_group_member_add_power`, `i_group_member_remove_power`, `i_client_move_power`, `i_client_poke_power`'],
            ['Temporary channel creator', 'Creates a temporary channel named after users who join the creator channel and moves them in; TeamSpeak deletes it when empty', '—', '`b_channel_create_temporary`, `i_client_move_power`'],
            ['Activity ranks', 'Counts time spent on the server and grants groups at hours defined like `10=12`', '`!time`, `!top`', '`i_group_member_add_power` (and `..._remove_power` to remove the previous rank)'],
            ['Channel guard', 'Moves or kicks users without an allowed group out of protected channels', '—', '`i_client_move_power` or `i_client_kick_from_channel_power`'],
            ['Anti-flood', 'Pokes users who send too many messages quickly and kicks repeat offenders from the channel/server', '—', 'kick powers, `i_client_poke_power`'],
            ['Vote skip', '`!next` doesn\'t skip immediately; it skips once a share of listeners voted (the requester and exempt groups skip directly)', '`!next`', '—'],
            ['DJ mode & queue limit', 'Limits adding songs to DJ groups and caps queued songs per user; optionally skip/pause/volume/stop for DJs only', '—', '—'],
            ['Scheduled messages', 'Sends messages at set days/times with lines like `21:00 | message` or `Sat,Sun 12:00 | message`', '—', 'server messages: `b_client_server_textmessage_send`'],
            ['Fun & tools (on by default)', 'Dice, coin flip, pick, polls, weather, currency, lyrics; turn off the commands you don\'t want', '`!dice`, `!coin`, `!pick`, `!poll`, `!vote`, `!weather`, `!fx`, `!usd`, `!eur`, `!lyrics`', '—']] }] },
      { id: 'newcmds', q: 'How do I use the new commands?',
        a: [['`!register John` — registers John in the registration channel. If several users match, the bot lists them; type the full name.', '`!playlist save rock` (save the queue) · `!playlist play rock` · `!playlist add rock` (add the current song) · `!playlist show rock` · `!playlist delete rock` · `!playlist` (all playlists). Playlists also appear on the panel\'s Playlists page.', '`!poll What do we play tonight? | CS2 | LoL | Valorant` → everyone types `!vote 2`; the result is posted when time is up (default 2 min) or with `!poll end`.', '`!weather istanbul` · `!fx EUR 50` · `!usd` · `!eur 20` · `!dice 2d6` · `!coin` · `!pick pizza | burger | sushi`', '`!lyrics` sends the current song\'s lyrics as a private message; `!lyrics never gonna give you up` searches another song.', '`!stats` shows the most played songs and top requesters of the last 30 days; the panel\'s Stats page shows more. `!time` shows your own time, `!top` the most active users.']] },
      { id: 'ranks', q: 'Activity ranks don\'t count time / !top is empty',
        a: ['The plugin must be enabled, and on one bot only (two bots would count time twice). Time is added once a minute. Write ranks as `hours=groupID`, one per line.'] },
      { id: 'tempchannel', q: 'The temporary channel isn\'t created',
        a: ['The bot needs permission to create temporary channels and move clients; the Logs page shows the reason ("could not create temporary channel"). A user gets at most one channel every 30 seconds.'] },
      { id: 'services', q: 'Which services do weather, currency and lyrics use?',
        a: ['Free services without API keys: open-meteo.com (weather), open.er-api.com (currency), lrclib.net (lyrics). Only the city, currency code or song name is sent — no user data. Results are cached briefly.'] },
    ] },
    { section: 'Commands & language', items: [
      { id: 'rename', q: 'Can I rename commands like !play and !next?',
        a: ['Yes: Commands → "Built-in commands". Enter a new name (e.g. `ara` → `play`) and save. Untick "keep old name" to disable the original. Command names in replies, the help text and the avatar update automatically.'] },
      { id: 'custom', q: 'How do I add my own command?',
        a: ['Commands → "Custom commands". Text replies with fixed text (e.g. `!discord` → invite link; `{user}`, `{args}`, `{time}`, `{date}` are available). Alias runs another command (e.g. `!song` → `!play`). Custom names can\'t clash with built-in commands.'] },
      { id: 'avatar', q: 'Why does the bot\'s avatar show a command list?',
        a: ['While idle, the avatar is drawn automatically from your commands (renamed commands, custom commands, and `!radio` if you have radio stations). Edit the descriptions via the `avatar.*` lines in Commands → "Bot texts". While playing, the avatar shows the song\'s cover. To use your own image instead, put `sleep.png` into `bots/<bot-name>/avatars/`.'] },
      { id: 'lang', q: 'I want the bot to reply in another language',
        a: ['Settings → "TeamSpeak reply language": Türkçe, English, Deutsch, Español, Français, Русский, Português, Polski, Italiano. Individual replies can be edited in Commands → "Bot texts". To set the built-in command names for a language too, use Commands → "Set command names for this language" (setup does this automatically for the chosen language; the Turkish names always keep working).'] },
    ] },
    { section: 'Installation', items: [
      { id: 'rights', q: '"You are missing the \'cmd.xxx\' right"',
        a: ['Add the command to the top `"+" = [ ... ]` list in `rights.toml` in the bot folder and restart. (Web panel users are not affected by this file.)'] },
      { id: 'commander', q: 'Channel commander doesn\'t turn on',
        a: ['The bot\'s server group needs the `b_client_use_channel_commander` permission. A warning is logged.'] },
      { id: 'connect', q: 'The bot can\'t connect',
        a: ['Use `ip:port` (default port 9987) and set the server password in the bot settings if needed. On first connect the server may require an identity security level; the bot computes it automatically (10-60 s). The log shows the reason.'] },
      { id: 'firewall', q: 'The panel is not reachable from outside',
        a: ['Open TCP 58913 in your firewall (Windows Firewall / `ufw allow 58913/tcp`) and in your cloud provider\'s network rules. If the first setup is done remotely, a setup code is required (`KURULUM_KODU.txt`).'] },
      { id: 'forgot', q: 'I forgot the admin password',
        a: ['Another admin can reset it on the Users page. If there is no admin left, stop the bot, delete `frix.db` and start again (radios, custom commands and plugin settings are reset; bots and TeamSpeak settings are kept).'] },
      { id: 'linux', q: 'No sound on Linux / "libopus" error',
        a: ['`sudo apt install libopus0 ffmpeg` (Debian/Ubuntu). `install.sh` installs them automatically. If installed under `/opt/frix`, check `systemctl status frix` and follow logs with `journalctl -u frix -f`.'] },
      { id: 'autostart', q: 'Start automatically after reboot',
        a: ['Windows: `Frix.exe` tray icon → "Start with Windows" (on by default). Linux: `install.sh` enables the systemd service (`systemctl enable frix`).'] },
    ] },
  ],
  de: [
    { section: 'Allgemein', items: [
      { id: 'nosound', q: 'Ein Song wird gefunden, aber es kommt kein Ton / "Song queue ended" im Log',
        a: ['Prüfe die gelben/roten Zeilen auf der Logs-Seite. Meist blockiert YouTube: Einstellungen → "yt-dlp aktualisieren"; hilft das nicht, lade YouTube-Cookies hoch (siehe unten). Ist der Bot nicht mit TeamSpeak verbunden ("verbindet"), wird kein Ton gesendet.'] },
      { id: 'cookies', q: '"Sign in to confirm you\'re not a bot" im Log',
        a: ['YouTube blockiert die Server-IP. Installiere die Browser-Erweiterung `Get cookies.txt LOCALLY`, exportiere angemeldet die `cookies.txt` für youtube.com und lade sie unter Einstellungen → YouTube-Cookies → "cookies.txt hochladen" hoch. Am besten nutzt du ein Zweitkonto bei Google.'] },
      { id: 'ytdlp', q: 'YouTube funktioniert plötzlich nicht mehr',
        a: ['YouTube ändert sich oft. Einstellungen → "yt-dlp aktualisieren".'] },
      { id: 'dupname', q: 'Der Bot erscheint als "Frix1"',
        a: ['Ein anderer Client mit demselben Nickname ist auf dem Server (ein alter Bot oder ein Reconnect, bevor die alte Sitzung abgelaufen ist). Schließe den anderen; beim nächsten Verbinden bekommt der Bot seinen Namen zurück.'] },
      { id: 'radio', q: 'Ein Radiosender spielt nicht',
        a: ['Nutze eine direkte Stream-URL (`.mp3`, `.aac`, Icecast/Shoutcast) oder einen `.m3u`-, `.pls`- oder `.m3u8`-Link. Teste ihn zuerst in VLC. Webseiten-URLs funktionieren nicht.'] },
      { id: 'live', q: 'Kann er Livestreams abspielen?',
        a: ['Ja: YouTube-Livestreams, Twitch und Internetradio. Bei Livestreams ist Spulen nicht möglich (der Player zeigt ein LIVE-Tag).'] },
      { id: 'roles', q: 'Was bedeuten die Rollen?',
        a: [['Admin: alles.', 'DJ: Songs/Radios hinzufügen und die Wiedergabe steuern.', 'Zuschauer: nur Lesen.']] },
      { id: 'multibot', q: 'Wie betreibe ich mehrere Bots?',
        a: ['Bots → "Neuer Bot" — z. B. ein Musik-Bot plus ein Begrüßungs-Bot, bei dem nur die Begrüßungs-/Ankündigungs-Plugins aktiviert sind. Jeder Bot verbindet sich als eigener TeamSpeak-Client.'] },
    ] },
    { section: 'Plugins', items: [
      { id: 'plugins', q: 'Wie werden Plugins konfiguriert und welche Berechtigungen brauchen sie?',
        a: ['Plugins werden pro Bot aktiviert: Plugins → Bot wählen → Karte aufklappen → konfigurieren → Speichern. Kanalfelder akzeptieren den Kanalnamen oder die ID (`5` oder `/5`). Gruppenfelder erwarten kommagetrennte Servergruppen-IDs (in TeamSpeak unter Permissions → Server Groups zu sehen).', { table: [
            ['Plugin', 'Was es macht', 'Benötigte Berechtigung des Bots'],
            ['Begrüßungsnachricht', 'Privatnachricht, Anstupsen oder Kanalnachricht für Benutzer, die den Server betreten / dem Kanal des Bots beitreten', '— (Anstupsen: `i_client_poke_power`)'],
            ['Ankündigungen / Werbung', 'Postet in Intervallen Nachrichten in den Kanal oder auf den Server (der Reihe nach oder zufällig)', 'Servernachrichten: `b_client_server_textmessage_send`'],
            ['Pause wenn allein', 'Pausiert, wenn niemand mehr im Kanal des Bots ist, und macht weiter, sobald jemand beitritt', '—'],
            ['Leerlauf-Radio', 'Spielt einen gewählten Radiosender, wenn die Warteschlange eine Weile leer war', '—'],
            ['AFK-Verschieber', 'Verschiebt inaktive, abwesende oder stummgeschaltete Benutzer in einen AFK-Kanal und zurück, wenn sie wiederkommen', '`i_client_move_power` (höher als `i_client_needed_move_power` des Ziels)'],
            ['Nickname-Filter', 'Verwarnt oder kickt Benutzer, deren Nickname ein verbotenes Wort enthält', 'Kick: `i_client_kick_from_server_power`'],
            ['Support-Benachrichtigung', 'Stupst Team-Mitglieder an, die online sind, wenn jemand den Support-Kanal betritt, und informiert den Benutzer', '`i_client_poke_power`'],
            ['Kanalname-Info', 'Hält einen Kanalnamen mit der Online-Anzahl und der Uhrzeit aktuell', '`b_channel_modify_name` (für diesen Kanal)']] }] },
      { id: 'afk', q: 'Der AFK-Verschieber verschiebt niemanden',
        a: [['Der "AFK-Kanal" muss genau dem Kanalnamen entsprechen (oder nutze seine ID). Wird er nicht gefunden, erscheint in den Logs eine Warnung "channel not found".', 'Die Move-Power des Bots muss höher sein als die des Benutzers. Server-Admins kann er nicht verschieben; füge sie außerdem zu "Ausgeschlossene Gruppen" hinzu.', 'Die Prüfung läuft alle 30 Sekunden, ein Verschieben kann sich also etwas verzögern.']] },
      { id: 'namefilter', q: 'Der Nickname-Filter erwischt die Falschen',
        a: ['Ein Wort passt an jeder Stelle des Nicknames (Groß-/Kleinschreibung egal). Vermeide sehr kurze Wörter und füge ausgenommene Gruppen zu "Ausgeschlossene Gruppen" hinzu. Fang mit "Anstupsen" an und wechsle zu "Kicken", wenn du dir sicher bist.'] },
      { id: 'support', q: 'Die Support-Benachrichtigung benachrichtigt niemanden',
        a: ['Ist "Team-Gruppen-IDs" leer oder niemand aus diesen Gruppen online, bekommt der Benutzer die Nachricht "kein Team da". Derselbe Benutzer wird erst nach Ablauf der Wartezeit (Standard 5 Min.) erneut gemeldet.'] },
      { id: 'channelinfo', q: 'Der Kanalname ändert sich nicht',
        a: ['Der Bot braucht die Berechtigung, den Namen dieses Kanals zu ändern (in den Logs erscheint eine Warnung "could not change channel name"). Kanalnamen sind auf 40 Zeichen begrenzt; längere Vorlagen werden abgeschnitten. Da sich der Name ändert, wähle den Kanal am besten per ID.'] },
      { id: 'welcome', q: 'Geht die Begrüßung beim Start des Bots an alle?',
        a: ['Nein. Beitritte in den ersten 15 Sekunden nach dem Verbinden des Bots (Leute, die schon online waren) werden ignoriert, und derselbe Benutzer wird vor Ablauf der "Wiederholen"-Zeit nicht erneut begrüßt.'] },
    ] },
    { section: 'Neue Plugins', items: [
      { id: 'newplugins', q: 'Was machen die neuen Plugins und welche Berechtigungen brauchen sie?',
        a: ['Alle werden pro Bot auf der Seite Plugins aktiviert. "Spaß & Tools" ist standardmäßig aktiv.', { table: [
            ['Plugin', 'Was es macht', 'Befehl', 'Benötigte Berechtigung des Bots'],
            ['Registrierung', 'Stupst das Team an, wenn ein nicht registrierter Benutzer den Registrierungskanal betritt; bei der Registrierung durch das Team erhält er die Mitgliedsgruppe, die Gruppe für Unregistrierte wird entfernt und er wird in die Lobby verschoben', '`!register <name>` (nur Team-Gruppen)', '`i_group_member_add_power`, `i_group_member_remove_power`, `i_client_move_power`, `i_client_poke_power`'],
            ['Temporäre Kanäle', 'Erstellt für Benutzer, die den Ersteller-Kanal betreten, einen temporären Kanal mit ihrem Namen und verschiebt sie hinein; TeamSpeak löscht ihn, sobald er leer ist', '—', '`b_channel_create_temporary`, `i_client_move_power`'],
            ['Aktivitätsränge', 'Zählt die auf dem Server verbrachte Zeit und vergibt Gruppen nach Stunden, festgelegt wie `10=12`', '`!time`, `!top`', '`i_group_member_add_power` (und `..._remove_power`, um den vorherigen Rang zu entfernen)'],
            ['Kanalschutz', 'Verschiebt oder kickt Benutzer ohne erlaubte Gruppe aus geschützten Kanälen', '—', '`i_client_move_power` oder `i_client_kick_from_channel_power`'],
            ['Anti-Flood', 'Stupst Benutzer an, die schnell zu viele Nachrichten senden, und kickt Wiederholungstäter aus dem Kanal/vom Server', '—', 'Kick-Berechtigungen, `i_client_poke_power`'],
            ['Skip-Abstimmung', '`!next` überspringt nicht sofort, sondern erst, wenn ein Anteil der Zuhörer abgestimmt hat (der Anfragende und ausgenommene Gruppen überspringen direkt)', '`!next`', '—'],
            ['DJ-Modus & Warteschlangenlimit', 'Beschränkt das Hinzufügen von Songs auf DJ-Gruppen und begrenzt die eingereihten Songs pro Benutzer; optional Überspringen/Pause/Lautstärke/Stopp nur für DJs', '—', '—'],
            ['Geplante Nachrichten', 'Sendet Nachrichten an festgelegten Tagen/Uhrzeiten mit Zeilen wie `21:00 | message` oder `Sat,Sun 12:00 | message`', '—', 'Servernachrichten: `b_client_server_textmessage_send`'],
            ['Spaß & Tools (standardmäßig aktiv)', 'Würfeln, Münzwurf, Auswahl, Umfragen, Wetter, Währungen, Songtexte; schalte die Befehle aus, die du nicht willst', '`!dice`, `!coin`, `!pick`, `!poll`, `!vote`, `!weather`, `!fx`, `!usd`, `!eur`, `!lyrics`', '—']] }] },
      { id: 'newcmds', q: 'Wie benutze ich die neuen Befehle?',
        a: [['`!register John` — registriert John im Registrierungskanal. Passen mehrere Benutzer, listet der Bot sie auf; tippe dann den vollständigen Namen.', '`!playlist save rock` (Warteschlange speichern) · `!playlist play rock` · `!playlist add rock` (aktuellen Song hinzufügen) · `!playlist show rock` · `!playlist delete rock` · `!playlist` (alle Playlists). Playlists erscheinen auch auf der Seite Playlists im Panel.', '`!poll What do we play tonight? | CS2 | LoL | Valorant` → alle tippen `!vote 2`; das Ergebnis wird gepostet, wenn die Zeit abgelaufen ist (Standard 2 Min.), oder mit `!poll end`.', '`!weather istanbul` · `!fx EUR 50` · `!usd` · `!eur 20` · `!dice 2d6` · `!coin` · `!pick pizza | burger | sushi`', '`!lyrics` schickt den Songtext des aktuellen Songs als Privatnachricht; `!lyrics never gonna give you up` sucht einen anderen Song.', '`!stats` zeigt die meistgespielten Songs und die Top-Anfragenden der letzten 30 Tage; die Seite Statistik im Panel zeigt mehr. `!time` zeigt deine eigene Zeit, `!top` die aktivsten Benutzer.']] },
      { id: 'ranks', q: 'Aktivitätsränge zählen keine Zeit / !top ist leer',
        a: ['Das Plugin muss aktiviert sein, und zwar nur auf einem Bot (zwei Bots würden die Zeit doppelt zählen). Die Zeit wird einmal pro Minute addiert. Schreibe Ränge als `hours=groupID`, einen pro Zeile.'] },
      { id: 'tempchannel', q: 'Der temporäre Kanal wird nicht erstellt',
        a: ['Der Bot braucht die Berechtigung, temporäre Kanäle zu erstellen und Clients zu verschieben; die Seite Logs zeigt den Grund ("could not create temporary channel"). Ein Benutzer bekommt höchstens alle 30 Sekunden einen Kanal.'] },
      { id: 'services', q: 'Welche Dienste nutzen Wetter, Währungen und Songtexte?',
        a: ['Kostenlose Dienste ohne API-Schlüssel: open-meteo.com (Wetter), open.er-api.com (Währungen), lrclib.net (Songtexte). Gesendet wird nur die Stadt, der Währungscode oder der Songname — keine Benutzerdaten. Ergebnisse werden kurz zwischengespeichert.'] },
    ] },
    { section: 'Befehle & Sprache', items: [
      { id: 'rename', q: 'Kann ich Befehle wie !play und !next umbenennen?',
        a: ['Ja: Befehle → "Eingebaute Befehle". Gib einen neuen Namen ein (z. B. `ara` → `play`) und speichere. Entferne den Haken bei "alten Namen behalten", um das Original zu deaktivieren. Befehlsnamen in Antworten, im Hilfetext und im Avatar werden automatisch angepasst.'] },
      { id: 'custom', q: 'Wie füge ich einen eigenen Befehl hinzu?',
        a: ['Befehle → "Eigene Befehle". Textantwort antwortet mit festem Text (z. B. `!discord` → Einladungslink; `{user}`, `{args}`, `{time}`, `{date}` sind verfügbar). Alias führt einen anderen Befehl aus (z. B. `!song` → `!play`). Eigene Namen dürfen nicht mit eingebauten Befehlen kollidieren.'] },
      { id: 'avatar', q: 'Warum zeigt der Avatar des Bots eine Befehlsliste?',
        a: ['Im Leerlauf wird der Avatar automatisch aus deinen Befehlen gezeichnet (umbenannte Befehle, eigene Befehle und `!radio`, wenn du Radiosender hast). Die Beschreibungen bearbeitest du über die `avatar.*`-Zeilen unter Befehle → "Bot-Texte". Während der Wiedergabe zeigt der Avatar das Cover des Songs. Für ein eigenes Bild lege `sleep.png` in `bots/<bot-name>/avatars/` ab.'] },
      { id: 'lang', q: 'Der Bot soll in einer anderen Sprache antworten',
        a: ['Optionen → "TeamSpeak-Antwortsprache": Türkçe, English, Deutsch, Español, Français, Русский, Português, Polski, Italiano. Einzelne Antworten kannst du unter Befehle → "Bot-Texte" bearbeiten. Um auch die Namen der integrierten Befehle für eine Sprache zu setzen, nutze Befehle → "Befehlsnamen für diese Sprache setzen" (die Einrichtung macht das für die gewählte Sprache automatisch; die türkischen Namen funktionieren immer weiter).'] },
    ] },
    { section: 'Installation', items: [
      { id: 'rights', q: '"You are missing the \'cmd.xxx\' right"',
        a: ['Füge den Befehl zur obersten Liste `"+" = [ ... ]` in `rights.toml` im Bot-Ordner hinzu und starte neu. (Web-Panel-Benutzer sind von dieser Datei nicht betroffen.)'] },
      { id: 'commander', q: 'Channel Commander lässt sich nicht einschalten',
        a: ['Die Servergruppe des Bots braucht die Berechtigung `b_client_use_channel_commander`. Eine Warnung wird geloggt.'] },
      { id: 'connect', q: 'Der Bot kann sich nicht verbinden',
        a: ['Nutze `ip:port` (Standardport 9987) und setze bei Bedarf das Serverpasswort in den Bot-Einstellungen. Beim ersten Verbinden verlangt der Server eventuell ein Identitäts-Sicherheitslevel; der Bot berechnet es automatisch (10-60 s). Das Log zeigt den Grund.'] },
      { id: 'firewall', q: 'Das Panel ist von außen nicht erreichbar',
        a: ['Öffne TCP 58913 in deiner Firewall (Windows-Firewall / `ufw allow 58913/tcp`) und in den Netzwerkregeln deines Cloud-Anbieters. Erfolgt die Ersteinrichtung aus der Ferne, ist ein Einrichtungscode nötig (`KURULUM_KODU.txt`).'] },
      { id: 'forgot', q: 'Ich habe das Admin-Passwort vergessen',
        a: ['Ein anderer Admin kann es auf der Benutzer-Seite zurücksetzen. Gibt es keinen Admin mehr, stoppe den Bot, lösche `frix.db` und starte neu (Radios, eigene Befehle und Plugin-Einstellungen werden zurückgesetzt; Bots und TeamSpeak-Einstellungen bleiben erhalten).'] },
      { id: 'linux', q: 'Kein Ton unter Linux / "libopus"-Fehler',
        a: ['`sudo apt install libopus0 ffmpeg` (Debian/Ubuntu). `install.sh` installiert sie automatisch. Bei Installation unter `/opt/frix` prüfe `systemctl status frix` und verfolge die Logs mit `journalctl -u frix -f`.'] },
      { id: 'autostart', q: 'Nach einem Neustart automatisch starten',
        a: ['Windows: Tray-Symbol von `Frix.exe` → "Mit Windows starten" (standardmäßig an). Linux: `install.sh` aktiviert den systemd-Dienst (`systemctl enable frix`).'] },
    ] },
  ],
  es: [
    { section: 'General', items: [
      { id: 'nosound', q: 'Encuentra la canción pero no hay sonido / "Song queue ended" en el registro',
        a: ['Revisa las líneas amarillas/rojas en la página Registros. Normalmente YouTube está bloqueando: Ajustes → "Actualizar yt-dlp"; si no sirve, sube cookies de YouTube (ver abajo). Si el bot no está conectado a TeamSpeak ("conectando"), no se envía audio.'] },
      { id: 'cookies', q: '"Sign in to confirm you\'re not a bot" en el registro',
        a: ['YouTube bloquea la IP del servidor. Instala la extensión del navegador `Get cookies.txt LOCALLY`, exporta `cookies.txt` de youtube.com con la sesión iniciada y súbelo en Ajustes → Cookies de YouTube → "Subir cookies.txt". Mejor usa una cuenta de Google secundaria.'] },
      { id: 'ytdlp', q: 'YouTube dejó de funcionar de repente',
        a: ['YouTube cambia a menudo. Ajustes → "Actualizar yt-dlp".'] },
      { id: 'dupname', q: 'El bot aparece como "Frix1"',
        a: ['Hay otro cliente con el mismo apodo en el servidor (un bot antiguo o una reconexión antes de que caducara la sesión anterior). Cierra el otro; el bot recuperará su nombre en la siguiente conexión.'] },
      { id: 'radio', q: 'Una emisora de radio no suena',
        a: ['Usa una URL de stream directa (`.mp3`, `.aac`, Icecast/Shoutcast) o un enlace `.m3u`, `.pls`, `.m3u8`. Pruébala antes en VLC. Las URL de páginas web no funcionan.'] },
      { id: 'live', q: '¿Puede reproducir directos?',
        a: ['Sí: directos de YouTube, Twitch y radio por internet. En los directos no se puede saltar a otra posición (el reproductor muestra la etiqueta EN VIVO).'] },
      { id: 'roles', q: '¿Qué significan los roles?',
        a: [['Admin: todo.', 'DJ: añadir canciones/radios y controlar la reproducción.', 'Espectador: solo lectura.']] },
      { id: 'multibot', q: '¿Cómo ejecuto varios bots?',
        a: ['Bots → "Nuevo bot" — p. ej. un bot de música más un bot de bienvenida que solo tenga activados los plugins de bienvenida/anuncios. Cada bot se conecta como su propio cliente de TeamSpeak.'] },
    ] },
    { section: 'Plugins', items: [
      { id: 'plugins', q: '¿Cómo se configuran los plugins y qué permisos necesitan?',
        a: ['Los plugins se activan por bot: Plugins → elige un bot → despliega la tarjeta → configura → Guardar. Los campos de canal aceptan el nombre o el ID del canal (`5` o `/5`). Los campos de grupo aceptan IDs de grupos de servidor separados por comas (se ven en TeamSpeak en Permisos → Grupos de servidor).', { table: [
            ['Plugin', 'Qué hace', 'Permiso que necesita el bot'],
            ['Mensaje de bienvenida', 'Mensaje privado, toque o mensaje de canal para los usuarios que se conectan / entran en el canal del bot', '— (toque: `i_client_poke_power`)'],
            ['Anuncios', 'Publica mensajes en el canal o el servidor cada cierto tiempo (en orden o aleatorio)', 'Mensajes de servidor: `b_client_server_textmessage_send`'],
            ['Pausar si está solo', 'Pausa cuando no queda nadie en el canal del bot y continúa cuando alguien entra', '—'],
            ['Radio en reposo', 'Reproduce la emisora elegida cuando la cola lleva un rato vacía', '—'],
            ['Mover AFK', 'Mueve a los usuarios inactivos, ausentes o con altavoces silenciados a un canal AFK y los devuelve cuando vuelven', '`i_client_move_power` (mayor que el `i_client_needed_move_power` del usuario)'],
            ['Filtro de apodos', 'Avisa o expulsa a los usuarios cuyo apodo contiene una palabra prohibida', 'Expulsar: `i_client_kick_from_server_power`'],
            ['Aviso de soporte', 'Da un toque al staff conectado cuando alguien entra en el canal de soporte e informa al usuario', '`i_client_poke_power`'],
            ['Info en nombre de canal', 'Mantiene el nombre de un canal actualizado con el número de conectados y la hora', '`b_channel_modify_name` (en ese canal)']] }] },
      { id: 'afk', q: 'Mover AFK no mueve a nadie',
        a: [['El "Canal AFK" debe coincidir exactamente con el nombre del canal (o usa su ID). Si no se encuentra, aparece un aviso "channel not found" en Registros.', 'El poder de mover del bot debe ser mayor que el del usuario. No puede mover a los admins del servidor; añádelos también a "Grupos excluidos".', 'Las comprobaciones se hacen cada 30 segundos, así que un movimiento puede tardar un poco.']] },
      { id: 'namefilter', q: 'El filtro de apodos pilla a quien no debe',
        a: ['Una palabra coincide en cualquier parte del apodo (sin distinguir mayúsculas). Evita palabras muy cortas y añade los grupos exentos a "Grupos excluidos". Empieza con "Toque" y cambia a "Expulsar" cuando estés seguro.'] },
      { id: 'support', q: 'El aviso de soporte no avisa a nadie',
        a: ['Si "IDs de grupos de staff" está vacío o no hay nadie de esos grupos conectado, el usuario recibe el mensaje de "sin staff". Al mismo usuario no se le vuelve a avisar hasta que pasa el tiempo de espera (5 min por defecto).'] },
      { id: 'channelinfo', q: 'El nombre del canal no cambia',
        a: ['El bot necesita permiso para editar el nombre de ese canal (aparece un aviso "could not change channel name" en Registros). Los nombres de canal tienen un límite de 40 caracteres; las plantillas más largas se recortan. Como el nombre cambia, mejor selecciona el canal por ID.'] },
      { id: 'welcome', q: '¿El mensaje de bienvenida se envía a todos cuando arranca el bot?',
        a: ['No. Las entradas durante los primeros 15 segundos tras conectarse el bot (gente que ya estaba conectada) se ignoran, y al mismo usuario no se le saluda de nuevo antes del tiempo de "repetición".'] },
    ] },
    { section: 'Plugins nuevos', items: [
      { id: 'newplugins', q: '¿Qué hacen los plugins nuevos y qué permisos necesitan?',
        a: ['Todos se activan por bot en la página Plugins. "Diversión y utilidades" está activado por defecto.', { table: [
            ['Plugin', 'Qué hace', 'Comando', 'Permiso que necesita el bot'],
            ['Registro', 'Da un toque al staff cuando un usuario no registrado entra en el canal de registro; al registrarlo, el staff le da el grupo de miembro, le quita el grupo de no registrado y lo mueve al lobby', '`!register <name>` (solo grupos de staff)', '`i_group_member_add_power`, `i_group_member_remove_power`, `i_client_move_power`, `i_client_poke_power`'],
            ['Creador de canales temporales', 'Crea un canal temporal con el nombre de quien entra en el canal creador y lo mueve dentro; TeamSpeak lo borra cuando queda vacío', '—', '`b_channel_create_temporary`, `i_client_move_power`'],
            ['Rangos de actividad', 'Cuenta el tiempo pasado en el servidor y asigna grupos según las horas definidas como `10=12`', '`!time`, `!top`', '`i_group_member_add_power` (y `..._remove_power` para quitar el rango anterior)'],
            ['Guardia de canal', 'Mueve o expulsa de los canales protegidos a los usuarios sin un grupo permitido', '—', '`i_client_move_power` o `i_client_kick_from_channel_power`'],
            ['Antiflood', 'Da un toque a quien envía muchos mensajes seguidos y expulsa del canal/servidor a los reincidentes', '—', 'permisos de expulsión, `i_client_poke_power`'],
            ['Saltar por votos', '`!next` no salta al instante; salta cuando vota una parte de los oyentes (quien pidió la canción y los grupos exentos saltan directamente)', '`!next`', '—'],
            ['Modo DJ y límite de cola', 'Solo los grupos DJ pueden añadir canciones y limita las canciones en cola por usuario; opcionalmente saltar/pausa/volumen/detener solo para DJs', '—', '—'],
            ['Mensajes programados', 'Envía mensajes en días/horas fijados con líneas como `21:00 | message` o `Sat,Sun 12:00 | message`', '—', 'mensajes de servidor: `b_client_server_textmessage_send`'],
            ['Diversión y utilidades (activado por defecto)', 'Dados, cara o cruz, elegir, encuestas, tiempo, divisas, letras; desactiva los comandos que no quieras', '`!dice`, `!coin`, `!pick`, `!poll`, `!vote`, `!weather`, `!fx`, `!usd`, `!eur`, `!lyrics`', '—']] }] },
      { id: 'newcmds', q: '¿Cómo uso los comandos nuevos?',
        a: [['`!register John` — registra a John en el canal de registro. Si coinciden varios usuarios, el bot los lista; escribe el nombre completo.', '`!playlist save rock` (guardar la cola) · `!playlist play rock` · `!playlist add rock` (añadir la canción actual) · `!playlist show rock` · `!playlist delete rock` · `!playlist` (todas las listas). Las listas también aparecen en la página Listas del panel.', '`!poll What do we play tonight? | CS2 | LoL | Valorant` → todos escriben `!vote 2`; el resultado se publica al acabar el tiempo (2 min por defecto) o con `!poll end`.', '`!weather istanbul` · `!fx EUR 50` · `!usd` · `!eur 20` · `!dice 2d6` · `!coin` · `!pick pizza | burger | sushi`', '`!lyrics` envía la letra de la canción actual por mensaje privado; `!lyrics never gonna give you up` busca otra canción.', '`!stats` muestra las canciones más reproducidas y quién pidió más en los últimos 30 días; la página Estadística del panel muestra más. `!time` muestra tu propio tiempo y `!top` los usuarios más activos.']] },
      { id: 'ranks', q: 'Los rangos de actividad no cuentan el tiempo / !top está vacío',
        a: ['El plugin debe estar activado, y solo en un bot (con dos bots el tiempo se contaría dos veces). El tiempo se suma una vez por minuto. Escribe los rangos como `hours=groupID`, uno por línea.'] },
      { id: 'tempchannel', q: 'No se crea el canal temporal',
        a: ['El bot necesita permiso para crear canales temporales y mover clientes; la página Registros muestra el motivo ("could not create temporary channel"). Cada usuario recibe como máximo un canal cada 30 segundos.'] },
      { id: 'services', q: '¿Qué servicios usan el tiempo, las divisas y las letras?',
        a: ['Servicios gratuitos sin claves de API: open-meteo.com (tiempo), open.er-api.com (divisas), lrclib.net (letras). Solo se envía la ciudad, el código de divisa o el nombre de la canción, ningún dato de usuario. Los resultados se guardan en caché un rato.'] },
    ] },
    { section: 'Comandos e idioma', items: [
      { id: 'rename', q: '¿Puedo renombrar comandos como !play y !next?',
        a: ['Sí: Comandos → "Comandos integrados". Escribe un nombre nuevo (p. ej. `ara` → `play`) y guarda. Desmarca "mantener el nombre antiguo" para desactivar el original. Los nombres de comando en las respuestas, el texto de ayuda y el avatar se actualizan solos.'] },
      { id: 'custom', q: '¿Cómo añado mi propio comando?',
        a: ['Comandos → "Comandos personalizados". Respuesta de texto responde con un texto fijo (p. ej. `!discord` → enlace de invitación; puedes usar `{user}`, `{args}`, `{time}`, `{date}`). Alias ejecuta otro comando (p. ej. `!song` → `!play`). Los nombres personalizados no pueden coincidir con comandos integrados.'] },
      { id: 'avatar', q: '¿Por qué el avatar del bot muestra una lista de comandos?',
        a: ['En reposo, el avatar se dibuja automáticamente a partir de tus comandos (comandos renombrados, comandos personalizados y `!radio` si tienes emisoras de radio). Edita las descripciones en las líneas `avatar.*` de Comandos → "Textos del bot". Mientras suena algo, el avatar muestra la portada de la canción. Para usar tu propia imagen, pon `sleep.png` en `bots/<bot-name>/avatars/`.'] },
      { id: 'lang', q: 'Quiero que el bot responda en otro idioma',
        a: ['Ajustes → "Idioma de respuestas en TeamSpeak": Türkçe, English, Deutsch, Español, Français, Русский, Português, Polski, Italiano. Puedes editar respuestas concretas en Comandos → "Textos del bot". Para usar también los nombres de los comandos integrados de un idioma, usa Comandos → "Usar nombres de comandos de este idioma" (la instalación lo hace automáticamente para el idioma elegido; los nombres en turco siempre siguen funcionando).'] },
    ] },
    { section: 'Instalación', items: [
      { id: 'rights', q: '"You are missing the \'cmd.xxx\' right"',
        a: ['Añade el comando a la lista `"+" = [ ... ]` del principio de `rights.toml` en la carpeta del bot y reinicia. (Este archivo no afecta a los usuarios del panel web.)'] },
      { id: 'commander', q: 'El comandante de canal no se activa',
        a: ['El grupo de servidor del bot necesita el permiso `b_client_use_channel_commander`. Se registra un aviso.'] },
      { id: 'connect', q: 'El bot no se puede conectar',
        a: ['Usa `ip:port` (puerto predeterminado 9987) y, si hace falta, pon la contraseña del servidor en los ajustes del bot. En la primera conexión el servidor puede exigir un nivel de seguridad de identidad; el bot lo calcula automáticamente (10-60 s). El registro muestra el motivo.'] },
      { id: 'firewall', q: 'No se puede acceder al panel desde fuera',
        a: ['Abre el puerto TCP 58913 en tu firewall (Firewall de Windows / `ufw allow 58913/tcp`) y en las reglas de red de tu proveedor cloud. Si la primera configuración se hace en remoto, se necesita un código de configuración (`KURULUM_KODU.txt`).'] },
      { id: 'forgot', q: 'Olvidé la contraseña de admin',
        a: ['Otro admin puede restablecerla en la página Usuarios. Si no queda ningún admin, detén el bot, borra `frix.db` y vuelve a iniciarlo (se restablecen las radios, los comandos personalizados y los ajustes de plugins; se conservan los bots y los ajustes de TeamSpeak).'] },
      { id: 'linux', q: 'Sin sonido en Linux / error "libopus"',
        a: ['`sudo apt install libopus0 ffmpeg` (Debian/Ubuntu). `install.sh` los instala automáticamente. Si está instalado en `/opt/frix`, revisa `systemctl status frix` y sigue los registros con `journalctl -u frix -f`.'] },
      { id: 'autostart', q: 'Iniciar automáticamente tras reiniciar',
        a: ['Windows: icono de `Frix.exe` en la bandeja → "Start with Windows" (activado por defecto). Linux: `install.sh` activa el servicio de systemd (`systemctl enable frix`).'] },
    ] },
  ],
  fr: [
    { section: 'Général', items: [
      { id: 'nosound', q: 'Un titre est trouvé mais il n\'y a pas de son / « Song queue ended » dans le journal',
        a: ['Vérifie les lignes jaunes/rouges sur la page Journaux. En général, c\'est YouTube qui bloque : Réglages → « Mettre à jour yt-dlp » ; si ça ne suffit pas, envoie des cookies YouTube (voir plus bas). Si le bot n\'est pas connecté à TeamSpeak (« connexion »), aucun son n\'est envoyé.'] },
      { id: 'cookies', q: '« Sign in to confirm you\'re not a bot » dans le journal',
        a: ['YouTube bloque l\'IP du serveur. Installe l\'extension de navigateur `Get cookies.txt LOCALLY`, exporte `cookies.txt` pour youtube.com en étant connecté, puis envoie-le dans Réglages → Cookies YouTube → « Envoyer cookies.txt ». Utilise de préférence un compte Google secondaire.'] },
      { id: 'ytdlp', q: 'YouTube ne fonctionne soudainement plus',
        a: ['YouTube change souvent. Réglages → « Mettre à jour yt-dlp ».'] },
      { id: 'dupname', q: 'Le bot apparaît sous le nom « Frix1 »',
        a: ['Un autre client avec le même pseudo est sur le serveur (un ancien bot, ou une reconnexion avant l\'expiration de l\'ancienne session). Ferme l\'autre ; le bot récupère son nom à la prochaine connexion.'] },
      { id: 'radio', q: 'Une station de radio ne joue pas',
        a: ['Utilise une URL de flux direct (`.mp3`, `.aac`, Icecast/Shoutcast) ou un lien `.m3u`, `.pls`, `.m3u8`. Teste-la d\'abord dans VLC. Les URL de pages web ne fonctionnent pas.'] },
      { id: 'live', q: 'Peut-il lire des flux en direct ?',
        a: ['Oui : les directs YouTube, Twitch et les radios internet. Impossible d\'avancer dans un flux en direct (le lecteur affiche l\'étiquette EN DIRECT).'] },
      { id: 'roles', q: 'Que signifient les rôles ?',
        a: [['Admin : tout.', 'DJ : ajouter des titres/radios et contrôler la lecture.', 'Spectateur : lecture seule.']] },
      { id: 'multibot', q: 'Comment faire tourner plusieurs bots ?',
        a: ['Bots → « Nouveau bot » — par ex. un bot musique plus un bot d\'accueil qui n\'a que les plugins de bienvenue/annonces activés. Chaque bot se connecte comme un client TeamSpeak distinct.'] },
    ] },
    { section: 'Plugins', items: [
      { id: 'plugins', q: 'Comment configurer les plugins et de quelles permissions ont-ils besoin ?',
        a: ['Les plugins s\'activent par bot : Plugins → choisis un bot → déplie la carte → configure → Enregistrer. Les champs de canal acceptent le nom ou l\'ID du canal (`5` ou `/5`). Les champs de groupe prennent des ID de groupes serveur séparés par des virgules (visibles dans TeamSpeak sous Permissions → Groupes serveur).', { table: [
            ['Plugin', 'Ce qu\'il fait', 'Permission requise pour le bot'],
            ['Message de bienvenue', 'Message privé, poke ou message de canal pour les utilisateurs qui se connectent / rejoignent le canal du bot', '— (poke : `i_client_poke_power`)'],
            ['Annonces / Pubs', 'Publie des messages dans le canal ou sur le serveur à intervalles (dans l\'ordre ou au hasard)', 'Messages serveur : `b_client_server_textmessage_send`'],
            ['Pause si seul', 'Met en pause quand il n\'y a plus personne dans le canal du bot, reprend quand quelqu\'un arrive', '—'],
            ['Radio d\'attente', 'Lance une station de radio choisie quand la file est vide depuis un moment', '—'],
            ['Déplacement AFK', 'Déplace les utilisateurs inactifs, absents ou au haut-parleur coupé vers un canal AFK, et les ramène à leur retour', '`i_client_move_power` (supérieur au `i_client_needed_move_power` de la cible)'],
            ['Filtre de pseudo', 'Avertit ou expulse les utilisateurs dont le pseudo contient un mot interdit', 'Expulsion : `i_client_kick_from_server_power`'],
            ['Alerte support', 'Poke l\'équipe en ligne quand quelqu\'un rejoint le canal de support et informe l\'utilisateur', '`i_client_poke_power`'],
            ['Infos dans le nom du canal', 'Met à jour un nom de canal avec le nombre de connectés et l\'heure', '`b_channel_modify_name` (sur ce canal)']] }] },
      { id: 'afk', q: 'Le déplacement AFK ne déplace personne',
        a: [['Le « canal AFK » doit correspondre exactement au nom du canal (ou utilise son ID). S\'il est introuvable, un avertissement « channel not found » apparaît dans les Journaux.', 'Le pouvoir de déplacement du bot doit être supérieur à celui de l\'utilisateur. Il ne peut pas déplacer les admins du serveur ; ajoute-les aussi aux « Groupes exclus ».', 'Les vérifications ont lieu toutes les 30 secondes, un déplacement peut donc être un peu retardé.']] },
      { id: 'namefilter', q: 'Le filtre de pseudo attrape les mauvaises personnes',
        a: ['Un mot est détecté n\'importe où dans le pseudo (sans tenir compte de la casse). Évite les mots très courts et ajoute les groupes exemptés aux « Groupes exclus ». Commence par « poke », passe à « kick » une fois sûr de toi.'] },
      { id: 'support', q: 'L\'alerte support ne prévient personne',
        a: ['Si « ID des groupes de l\'équipe » est vide ou si personne de ces groupes n\'est en ligne, l\'utilisateur reçoit le message « aucun membre de l\'équipe ». Le même utilisateur n\'est pas re-notifié avant la fin du délai (5 min par défaut).'] },
      { id: 'channelinfo', q: 'Le nom du canal ne change pas',
        a: ['Le bot a besoin de la permission de modifier le nom de ce canal (un avertissement « could not change channel name » apparaît dans les Journaux). Les noms de canal sont limités à 40 caractères ; les modèles plus longs sont coupés. Comme le nom change, sélectionne plutôt le canal par ID.'] },
      { id: 'welcome', q: 'Le message de bienvenue est-il envoyé à tout le monde au démarrage du bot ?',
        a: ['Non. Les arrivées pendant les 15 premières secondes après la connexion du bot (les personnes déjà en ligne) sont ignorées, et le même utilisateur n\'est pas re-salué avant le délai de « répétition ».'] },
    ] },
    { section: 'Nouveaux plugins', items: [
      { id: 'newplugins', q: 'Que font les nouveaux plugins et de quelles permissions ont-ils besoin ?',
        a: ['Ils s\'activent tous par bot sur la page Plugins. « Fun et outils » est activé par défaut.', { table: [
            ['Plugin', 'Ce qu\'il fait', 'Commande', 'Permission requise pour le bot'],
            ['Enregistrement', 'Poke l\'équipe quand un utilisateur non enregistré rejoint le canal d\'enregistrement ; l\'enregistrement par l\'équipe donne le groupe membre, retire le groupe non enregistré et déplace l\'utilisateur vers le hall', '`!register <name>` (groupes de l\'équipe uniquement)', '`i_group_member_add_power`, `i_group_member_remove_power`, `i_client_move_power`, `i_client_poke_power`'],
            ['Créateur de canaux temporaires', 'Crée un canal temporaire au nom des utilisateurs qui rejoignent le canal créateur et les y déplace ; TeamSpeak le supprime quand il est vide', '—', '`b_channel_create_temporary`, `i_client_move_power`'],
            ['Rangs d\'activité', 'Compte le temps passé sur le serveur et attribue des groupes selon les heures définies comme `10=12`', '`!time`, `!top`', '`i_group_member_add_power` (et `..._remove_power` pour retirer le rang précédent)'],
            ['Garde de canal', 'Déplace ou expulse des canaux protégés les utilisateurs sans groupe autorisé', '—', '`i_client_move_power` ou `i_client_kick_from_channel_power`'],
            ['Anti-flood', 'Poke les utilisateurs qui envoient trop de messages trop vite et expulse les récidivistes du canal/serveur', '—', 'Permissions d\'expulsion, `i_client_poke_power`'],
            ['Vote pour passer', '`!next` ne passe pas le titre tout de suite ; il est passé quand une part des auditeurs a voté (le demandeur et les groupes exemptés passent directement)', '`!next`', '—'],
            ['Mode DJ et limite de file', 'Réserve l\'ajout de titres aux groupes DJ et limite le nombre de titres en file par utilisateur ; en option, passer/pause/volume/arrêt réservés aux DJ', '—', '—'],
            ['Messages programmés', 'Envoie des messages aux jours/heures définis avec des lignes comme `21:00 | message` ou `Sat,Sun 12:00 | message`', '—', 'Messages serveur : `b_client_server_textmessage_send`'],
            ['Fun et outils (activé par défaut)', 'Dés, pile ou face, tirage au sort, sondages, météo, devises, paroles ; désactive les commandes dont tu ne veux pas', '`!dice`, `!coin`, `!pick`, `!poll`, `!vote`, `!weather`, `!fx`, `!usd`, `!eur`, `!lyrics`', '—']] }] },
      { id: 'newcmds', q: 'Comment utiliser les nouvelles commandes ?',
        a: [['`!register John` — enregistre John dans le canal d\'enregistrement. Si plusieurs utilisateurs correspondent, le bot les liste ; tape le nom complet.', '`!playlist save rock` (enregistre la file) · `!playlist play rock` · `!playlist add rock` (ajoute le titre en cours) · `!playlist show rock` · `!playlist delete rock` · `!playlist` (toutes les playlists). Les playlists apparaissent aussi sur la page Playlists du panneau.', '`!poll What do we play tonight? | CS2 | LoL | Valorant` → chacun tape `!vote 2` ; le résultat est publié à la fin du temps (2 min par défaut) ou avec `!poll end`.', '`!weather istanbul` · `!fx EUR 50` · `!usd` · `!eur 20` · `!dice 2d6` · `!coin` · `!pick pizza | burger | sushi`', '`!lyrics` envoie les paroles du titre en cours en message privé ; `!lyrics never gonna give you up` cherche un autre titre.', '`!stats` affiche les titres les plus écoutés et les top demandeurs des 30 derniers jours ; la page Stats du panneau en montre plus. `!time` affiche ton propre temps, `!top` les utilisateurs les plus actifs.']] },
      { id: 'ranks', q: 'Les rangs d\'activité ne comptent pas le temps / !top est vide',
        a: ['Le plugin doit être activé, et sur un seul bot (deux bots compteraient le temps en double). Le temps est ajouté une fois par minute. Écris les rangs sous la forme `hours=groupID`, un par ligne.'] },
      { id: 'tempchannel', q: 'Le canal temporaire n\'est pas créé',
        a: ['Le bot a besoin de la permission de créer des canaux temporaires et de déplacer des clients ; la page Journaux indique la raison (« could not create temporary channel »). Un utilisateur obtient au plus un canal toutes les 30 secondes.'] },
      { id: 'services', q: 'Quels services utilisent la météo, les devises et les paroles ?',
        a: ['Des services gratuits sans clé API : open-meteo.com (météo), open.er-api.com (devises), lrclib.net (paroles). Seuls la ville, le code de devise ou le nom du titre sont envoyés — aucune donnée utilisateur. Les résultats sont mis en cache brièvement.'] },
    ] },
    { section: 'Commandes et langue', items: [
      { id: 'rename', q: 'Puis-je renommer des commandes comme !play et !next ?',
        a: ['Oui : Commandes → « Commandes intégrées ». Saisis un nouveau nom (ex. `ara` → `play`) et enregistre. Décoche « garder l\'ancien nom actif » pour désactiver l\'original. Les noms de commandes dans les réponses, le texte d\'aide et l\'avatar se mettent à jour automatiquement.'] },
      { id: 'custom', q: 'Comment ajouter ma propre commande ?',
        a: ['Commandes → « Commandes perso ». « Réponse texte » répond avec un texte fixe (ex. `!discord` → lien d\'invitation ; `{user}`, `{args}`, `{time}`, `{date}` sont disponibles). « Alias » exécute une autre commande (ex. `!song` → `!play`). Les noms perso ne peuvent pas entrer en conflit avec les commandes intégrées.'] },
      { id: 'avatar', q: 'Pourquoi l\'avatar du bot affiche-t-il une liste de commandes ?',
        a: ['Au repos, l\'avatar est généré automatiquement à partir de tes commandes (commandes renommées, commandes perso, et `!radio` si tu as des stations de radio). Modifie les descriptions via les lignes `avatar.*` dans Commandes → « Textes du bot ». Pendant la lecture, l\'avatar affiche la pochette du titre. Pour utiliser ta propre image, place `sleep.png` dans `bots/<bot-name>/avatars/`.'] },
      { id: 'lang', q: 'Je veux que le bot réponde dans une autre langue',
        a: ['Réglages → « Langue des réponses TeamSpeak » : Türkçe, English, Deutsch, Español, Français, Русский, Português, Polski, Italiano. Chaque réponse peut être modifiée dans Commandes → « Textes du bot ». Pour appliquer aussi les noms des commandes intégrées d\'une langue, utilise Commandes → « Appliquer les noms de commandes de cette langue » (l\'installation le fait automatiquement pour la langue choisie ; les noms turcs fonctionnent toujours).'] },
    ] },
    { section: 'Installation', items: [
      { id: 'rights', q: '« You are missing the \'cmd.xxx\' right »',
        a: ['Ajoute la commande à la liste `"+" = [ ... ]` en haut de `rights.toml` dans le dossier du bot, puis redémarre. (Les utilisateurs du panneau web ne sont pas concernés par ce fichier.)'] },
      { id: 'commander', q: 'Le commandant de canal ne s\'active pas',
        a: ['Le groupe serveur du bot a besoin de la permission `b_client_use_channel_commander`. Un avertissement est enregistré dans le journal.'] },
      { id: 'connect', q: 'Le bot n\'arrive pas à se connecter',
        a: ['Utilise `ip:port` (port par défaut 9987) et indique le mot de passe du serveur dans les réglages du bot si nécessaire. À la première connexion, le serveur peut exiger un niveau de sécurité d\'identité ; le bot le calcule automatiquement (10 à 60 s). Le journal indique la raison.'] },
      { id: 'firewall', q: 'Le panneau n\'est pas accessible depuis l\'extérieur',
        a: ['Ouvre le port TCP 58913 dans ton pare-feu (Pare-feu Windows / `ufw allow 58913/tcp`) et dans les règles réseau de ton hébergeur cloud. Si la première installation se fait à distance, un code d\'installation est requis (`KURULUM_KODU.txt`).'] },
      { id: 'forgot', q: 'J\'ai oublié le mot de passe admin',
        a: ['Un autre admin peut le réinitialiser sur la page Utilisateurs. S\'il n\'y a plus d\'admin, arrête le bot, supprime `frix.db` et relance-le (radios, commandes perso et réglages des plugins sont réinitialisés ; les bots et les réglages TeamSpeak sont conservés).'] },
      { id: 'linux', q: 'Pas de son sous Linux / erreur « libopus »',
        a: ['`sudo apt install libopus0 ffmpeg` (Debian/Ubuntu). `install.sh` les installe automatiquement. Si installé dans `/opt/frix`, vérifie `systemctl status frix` et suis les journaux avec `journalctl -u frix -f`.'] },
      { id: 'autostart', q: 'Démarrage automatique après un redémarrage',
        a: ['Windows : icône `Frix.exe` dans la zone de notification → « Démarrer avec Windows » (activé par défaut). Linux : `install.sh` active le service systemd (`systemctl enable frix`).'] },
    ] },
  ],
  ru: [
    { section: 'Общее', items: [
      { id: 'nosound', q: 'Трек находится, но звука нет / в логе "Song queue ended"',
        a: ['Проверь жёлтые/красные строки на странице «Логи». Обычно это блокировка со стороны YouTube: Настройки → «Обновить yt-dlp»; если не помогло, загрузи cookies YouTube (см. ниже). Если бот не подключён к TeamSpeak («Подключение»), звук не передаётся.'] },
      { id: 'cookies', q: 'В логе "Sign in to confirm you\'re not a bot"',
        a: ['YouTube блокирует IP сервера. Установи расширение браузера `Get cookies.txt LOCALLY`, войди на youtube.com, экспортируй `cookies.txt` и загрузи его в Настройки → Cookies YouTube → «Загрузить cookies.txt». Лучше используй запасной аккаунт Google.'] },
      { id: 'ytdlp', q: 'YouTube вдруг перестал работать',
        a: ['YouTube часто что-то меняет. Настройки → «Обновить yt-dlp».'] },
      { id: 'dupname', q: 'Бот отображается как "Frix1"',
        a: ['На сервере есть другой клиент с таким же ником (старый бот или переподключение до того, как истекла старая сессия). Закрой другой клиент — при следующем подключении бот вернёт своё имя.'] },
      { id: 'radio', q: 'Радиостанция не играет',
        a: ['Используй прямой URL потока (`.mp3`, `.aac`, Icecast/Shoutcast) или ссылку `.m3u`, `.pls`, `.m3u8`. Сначала проверь её в VLC. Ссылки на веб-страницы не работают.'] },
      { id: 'live', q: 'Можно ли играть прямые трансляции?',
        a: ['Да: прямые эфиры YouTube, Twitch и интернет-радио. Перемотка в прямом эфире недоступна (плеер показывает метку ЭФИР).'] },
      { id: 'roles', q: 'Что означают роли?',
        a: [['Админ: всё.', 'DJ: добавляет треки/радио и управляет воспроизведением.', 'Зритель: только просмотр.']] },
      { id: 'multibot', q: 'Как запустить несколько ботов?',
        a: ['Боты → «Новый бот» — например, музыкальный бот плюс бот-приветствие, у которого включены только плагины приветствия/объявлений. Каждый бот подключается как отдельный клиент TeamSpeak.'] },
    ] },
    { section: 'Плагины', items: [
      { id: 'plugins', q: 'Как настраиваются плагины и какие права им нужны?',
        a: ['Плагины включаются для каждого бота отдельно: Плагины → выбери бота → разверни карточку → настрой → Сохранить. В полях канала можно указать имя или ID канала (`5` или `/5`). В полях групп указываются ID серверных групп через запятую (их видно в TeamSpeak в разделе Permissions → Server Groups).', { table: [
            ['Плагин', 'Что делает', 'Какие права нужны боту'],
            ['Приветствие', 'Личное сообщение, тычок или сообщение в канал для тех, кто подключается / заходит в канал бота', '— (тычок: `i_client_poke_power`)'],
            ['Объявления / Реклама', 'Периодически публикует сообщения в канал или на сервер (по порядку или случайно)', 'Сообщения на сервер: `b_client_server_textmessage_send`'],
            ['Пауза в одиночестве', 'Ставит на паузу, когда в канале бота никого не осталось, и продолжает, когда кто-то заходит', '—'],
            ['Радио в простое', 'Включает выбранную радиостанцию, если очередь какое-то время пуста', '—'],
            ['Перенос AFK', 'Переносит неактивных, отошедших или с выключенным звуком пользователей в AFK-канал и возвращает их обратно', '`i_client_move_power` (выше, чем `i_client_needed_move_power` цели)'],
            ['Фильтр ников', 'Предупреждает или кикает пользователей, в нике которых есть запрещённое слово', 'Кик: `i_client_kick_from_server_power`'],
            ['Вызов поддержки', 'Тычет онлайн-модераторов, когда кто-то заходит в канал поддержки, и сообщает об этом пользователю', '`i_client_poke_power`'],
            ['Инфо в имени канала', 'Обновляет имя канала: число онлайн и время', '`b_channel_modify_name` (на этом канале)']] }] },
      { id: 'afk', q: 'Перенос AFK никого не переносит',
        a: [['«AFK-канал» должен точно совпадать с именем канала (или укажи его ID). Если канал не найден, в логах появится предупреждение "channel not found".', 'Сила перемещения у бота должна быть выше, чем у пользователя. Админов сервера он переносить не может; добавь их также в «Исключённые группы».', 'Проверка идёт каждые 30 секунд, поэтому перенос может немного запаздывать.']] },
      { id: 'namefilter', q: 'Фильтр ников ловит не тех',
        a: ['Слово ищется в любом месте ника (без учёта регистра). Избегай очень коротких слов и добавь исключённые группы в «Исключённые группы». Начни с «Тычок», переключайся на «Кик», когда будешь уверен.'] },
      { id: 'support', q: 'Вызов поддержки никого не уведомляет',
        a: ['Если поле «ID групп персонала» пустое или из этих групп никого нет онлайн, пользователь получает сообщение «нет персонала». Того же пользователя не уведомят повторно, пока не пройдёт пауза (по умолчанию 5 мин).'] },
      { id: 'channelinfo', q: 'Имя канала не меняется',
        a: ['Боту нужно право менять имя этого канала (в логах появится предупреждение "could not change channel name"). Имя канала ограничено 40 символами; более длинные шаблоны обрезаются. Так как имя меняется, лучше выбирать канал по ID.'] },
      { id: 'welcome', q: 'Приветствие получают все при запуске бота?',
        a: ['Нет. Входы в первые 15 секунд после подключения бота (те, кто уже был онлайн) игнорируются, а того же пользователя не приветствуют снова, пока не пройдёт время «повтора».'] },
    ] },
    { section: 'Новые плагины', items: [
      { id: 'newplugins', q: 'Что делают новые плагины и какие права им нужны?',
        a: ['Все они включаются для каждого бота отдельно на странице «Плагины». «Развлечения и утилиты» включён по умолчанию.', { table: [
            ['Плагин', 'Что делает', 'Команда', 'Какие права нужны боту'],
            ['Регистрация', 'Тычет модераторов, когда незарегистрированный пользователь заходит в канал регистрации; регистрация модератором выдаёт группу участника, снимает группу незарегистрированных и переносит пользователя в лобби', '`!register <name>` (только группы модераторов)', '`i_group_member_add_power`, `i_group_member_remove_power`, `i_client_move_power`, `i_client_poke_power`'],
            ['Временные каналы', 'Создаёт временный канал с именем пользователя, зашедшего в канал-создатель, и переносит его туда; TeamSpeak удаляет канал, когда он пустеет', '—', '`b_channel_create_temporary`, `i_client_move_power`'],
            ['Ранги активности', 'Считает время на сервере и выдаёт группы по часам, заданным в виде `10=12`', '`!time`, `!top`', '`i_group_member_add_power` (и `..._remove_power`, чтобы снять предыдущий ранг)'],
            ['Охрана каналов', 'Переносит или кикает из защищённых каналов пользователей без разрешённой группы', '—', '`i_client_move_power` или `i_client_kick_from_channel_power`'],
            ['Антифлуд', 'Тычет тех, кто слишком быстро шлёт много сообщений, и кикает повторных нарушителей из канала/с сервера', '—', 'права на кик, `i_client_poke_power`'],
            ['Пропуск голосованием', '`!next` не пропускает трек сразу: пропуск происходит, когда проголосует нужная доля слушателей (заказчик и исключённые группы пропускают сразу)', '`!next`', '—'],
            ['Режим DJ и лимит очереди', 'Разрешает добавлять треки только группам DJ и ограничивает число треков в очереди на пользователя; по желанию пропуск/пауза/громкость/стоп только для DJ', '—', '—'],
            ['Сообщения по расписанию', 'Отправляет сообщения в заданные дни/время по строкам вида `21:00 | message` или `Sat,Sun 12:00 | message`', '—', 'сообщения на сервер: `b_client_server_textmessage_send`'],
            ['Развлечения и утилиты (включён по умолчанию)', 'Кубики, монетка, случайный выбор, опросы, погода, курсы валют, тексты песен; ненужные команды можно выключить', '`!dice`, `!coin`, `!pick`, `!poll`, `!vote`, `!weather`, `!fx`, `!usd`, `!eur`, `!lyrics`', '—']] }] },
      { id: 'newcmds', q: 'Как пользоваться новыми командами?',
        a: [['`!register John` — регистрирует John в канале регистрации. Если подходит несколько пользователей, бот их перечислит; введи полное имя.', '`!playlist save rock` (сохранить очередь) · `!playlist play rock` · `!playlist add rock` (добавить текущий трек) · `!playlist show rock` · `!playlist delete rock` · `!playlist` (все плейлисты). Плейлисты также видны на странице «Плейлисты» в панели.', '`!poll What do we play tonight? | CS2 | LoL | Valorant` → все пишут `!vote 2`; результат публикуется по истечении времени (по умолчанию 2 мин) или по `!poll end`.', '`!weather istanbul` · `!fx EUR 50` · `!usd` · `!eur 20` · `!dice 2d6` · `!coin` · `!pick pizza | burger | sushi`', '`!lyrics` присылает текст текущего трека личным сообщением; `!lyrics never gonna give you up` ищет другую песню.', '`!stats` показывает самые популярные треки и топ заказчиков за последние 30 дней; на странице «Статистика» в панели — подробнее. `!time` показывает твоё время, `!top` — самых активных пользователей.']] },
      { id: 'ranks', q: 'Ранги активности не считают время / !top пустой',
        a: ['Плагин должен быть включён, причём только на одном боте (два бота посчитают время дважды). Время добавляется раз в минуту. Ранги записываются как `hours=groupID`, по одному на строку.'] },
      { id: 'tempchannel', q: 'Временный канал не создаётся',
        a: ['Боту нужны права на создание временных каналов и перенос клиентов; причину видно на странице «Логи» ("could not create temporary channel"). Один пользователь получает не больше одного канала раз в 30 секунд.'] },
      { id: 'services', q: 'Какие сервисы используются для погоды, курсов валют и текстов песен?',
        a: ['Бесплатные сервисы без API-ключей: open-meteo.com (погода), open.er-api.com (курсы валют), lrclib.net (тексты песен). Отправляется только город, код валюты или название песни — никаких данных пользователей. Результаты ненадолго кэшируются.'] },
    ] },
    { section: 'Команды и язык', items: [
      { id: 'rename', q: 'Можно переименовать команды вроде !play и !next?',
        a: ['Да: Команды → «Встроенные команды». Введи новое имя (например, `ara` → `play`) и сохрани. Сними галочку «оставить старое имя рабочим», чтобы отключить исходное. Имена команд в ответах, справке и на аватаре обновятся автоматически.'] },
      { id: 'custom', q: 'Как добавить свою команду?',
        a: ['Команды → «Свои команды». Текстовый ответ отвечает фиксированным текстом (например, `!discord` → ссылка-приглашение; доступны `{user}`, `{args}`, `{time}`, `{date}`). Псевдоним запускает другую команду (например, `!song` → `!play`). Свои имена не могут совпадать со встроенными командами.'] },
      { id: 'avatar', q: 'Почему на аватаре бота список команд?',
        a: ['В простое аватар рисуется автоматически по твоим командам (переименованные команды, свои команды и `!radio`, если есть радиостанции). Описания меняются в строках `avatar.*` в Команды → «Тексты бота». Во время воспроизведения на аватаре обложка трека. Чтобы использовать свою картинку, положи `sleep.png` в `bots/<bot-name>/avatars/`.'] },
      { id: 'lang', q: 'Хочу, чтобы бот отвечал на другом языке',
        a: ['Настройки → «Язык ответов в TeamSpeak»: Türkçe, English, Deutsch, Español, Français, Русский, Português, Polski, Italiano. Отдельные ответы можно изменить в Команды → «Тексты бота». Чтобы задать для языка и встроенные названия команд, используй Команды → «Названия команд для этого языка» (при установке это делается автоматически для выбранного языка; турецкие названия всегда продолжают работать).'] },
    ] },
    { section: 'Установка', items: [
      { id: 'rights', q: '"You are missing the \'cmd.xxx\' right"',
        a: ['Добавь команду в верхний список `"+" = [ ... ]` в файле `rights.toml` в папке бота и перезапусти. (На пользователей веб-панели этот файл не влияет.)'] },
      { id: 'commander', q: 'Командир канала не включается',
        a: ['Серверной группе бота нужно право `b_client_use_channel_commander`. В лог пишется предупреждение.'] },
      { id: 'connect', q: 'Бот не может подключиться',
        a: ['Используй `ip:port` (порт по умолчанию 9987) и при необходимости укажи пароль сервера в настройках бота. При первом подключении сервер может требовать уровень безопасности идентификатора; бот вычисляет его автоматически (10–60 с). Причина видна в логе.'] },
      { id: 'firewall', q: 'Панель недоступна извне',
        a: ['Открой TCP 58913 в файрволе (Windows Firewall / `ufw allow 58913/tcp`) и в сетевых правилах облачного провайдера. Если первая настройка выполняется удалённо, нужен код установки (`KURULUM_KODU.txt`).'] },
      { id: 'forgot', q: 'Я забыл пароль администратора',
        a: ['Другой админ может сбросить его на странице «Пользователи». Если админов не осталось, останови бота, удали `frix.db` и запусти снова (радио, свои команды и настройки плагинов сбросятся; боты и настройки TeamSpeak сохранятся).'] },
      { id: 'linux', q: 'Нет звука в Linux / ошибка "libopus"',
        a: ['`sudo apt install libopus0 ffmpeg` (Debian/Ubuntu). `install.sh` устанавливает их автоматически. Если установлено в `/opt/frix`, проверь `systemctl status frix` и следи за логами через `journalctl -u frix -f`.'] },
      { id: 'autostart', q: 'Автозапуск после перезагрузки',
        a: ['Windows: значок `Frix.exe` в трее → "Start with Windows" (включено по умолчанию). Linux: `install.sh` включает службу systemd (`systemctl enable frix`).'] },
    ] },
  ],
  pt: [
    { section: 'Geral', items: [
      { id: 'nosound', q: 'A música é encontrada, mas não há som / "Song queue ended" no log',
        a: ['Confira as linhas amarelas/vermelhas na página Logs. Geralmente é o YouTube bloqueando: Ajustes → "Atualizar yt-dlp"; se não resolver, envie os cookies do YouTube (abaixo). Se o bot não estiver conectado ao TeamSpeak ("conectando"), nenhum áudio é enviado.'] },
      { id: 'cookies', q: '"Sign in to confirm you\'re not a bot" no log',
        a: ['O YouTube bloqueia o IP do servidor. Instale a extensão de navegador `Get cookies.txt LOCALLY`, exporte o `cookies.txt` do youtube.com estando logado e envie-o em Ajustes → Cookies do YouTube → "Enviar cookies.txt". De preferência, use uma conta Google secundária.'] },
      { id: 'ytdlp', q: 'O YouTube parou de funcionar de repente',
        a: ['O YouTube muda com frequência. Ajustes → "Atualizar yt-dlp".'] },
      { id: 'dupname', q: 'O bot aparece como "Frix1"',
        a: ['Há outro cliente com o mesmo apelido no servidor (um bot antigo ou uma reconexão antes de a sessão anterior expirar). Feche o outro; o bot recupera o nome na próxima conexão.'] },
      { id: 'radio', q: 'Uma estação de rádio não toca',
        a: ['Use uma URL de stream direta (`.mp3`, `.aac`, Icecast/Shoutcast) ou um link `.m3u`, `.pls`, `.m3u8`. Teste primeiro no VLC. URLs de páginas web não funcionam.'] },
      { id: 'live', q: 'Ele toca transmissões ao vivo?',
        a: ['Sim: YouTube ao vivo, Twitch e rádios da internet. Não é possível avançar/voltar em transmissões ao vivo (o player mostra a etiqueta AO VIVO).'] },
      { id: 'roles', q: 'O que significam as funções?',
        a: [['Admin: tudo.', 'DJ: adiciona músicas/rádios e controla a reprodução.', 'Espectador: somente leitura.']] },
      { id: 'multibot', q: 'Como executo vários bots?',
        a: ['Bots → "Novo bot" — ex.: um bot de música mais um bot de boas-vindas com apenas os plugins de boas-vindas/anúncios ativados. Cada bot se conecta como um cliente próprio do TeamSpeak.'] },
    ] },
    { section: 'Plugins', items: [
      { id: 'plugins', q: 'Como os plugins são configurados e de quais permissões precisam?',
        a: ['Os plugins são ativados por bot: Plugins → escolha um bot → expanda o cartão → configure → Salvar. Campos de canal aceitam o nome ou o ID do canal (`5` ou `/5`). Campos de grupo recebem IDs de grupos do servidor separados por vírgula (exibidos no TeamSpeak em Permissions → Server Groups).', { table: [
            ['Plugin', 'O que faz', 'Permissão necessária para o bot'],
            ['Mensagem de boas-vindas', 'Mensagem privada, cutucada ou mensagem no canal para usuários que se conectam / entram no canal do bot', '— (cutucada: `i_client_poke_power`)'],
            ['Anúncios / Propagandas', 'Envia mensagens ao canal ou ao servidor em intervalos (em ordem ou aleatório)', 'Mensagens no servidor: `b_client_server_textmessage_send`'],
            ['Pausar quando sozinho', 'Pausa quando não sobra ninguém no canal do bot e retoma quando alguém entra', '—'],
            ['Rádio em espera', 'Toca uma estação de rádio escolhida quando a fila fica vazia por um tempo', '—'],
            ['Mover AFK', 'Move usuários ociosos, ausentes ou com alto-falante mudo para um canal AFK e os traz de volta quando retornam', '`i_client_move_power` (maior que o `i_client_needed_move_power` do alvo)'],
            ['Filtro de apelidos', 'Avisa ou expulsa usuários cujo apelido contém uma palavra proibida', 'Expulsar: `i_client_kick_from_server_power`'],
            ['Aviso de suporte', 'Cutuca a equipe online quando alguém entra no canal de suporte e informa o usuário', '`i_client_poke_power`'],
            ['Info no nome do canal', 'Mantém o nome de um canal atualizado com o número de pessoas online e a hora', '`b_channel_modify_name` (nesse canal)']] }] },
      { id: 'afk', q: 'O Mover AFK não move ninguém',
        a: [['O "Canal AFK" deve corresponder exatamente ao nome do canal (ou use o ID). Se não for encontrado, um aviso "canal não encontrado" aparece em Logs.', 'O poder de mover do bot deve ser maior que o do usuário. Ele não consegue mover admins do servidor; adicione-os também em "Grupos excluídos".', 'As verificações rodam a cada 30 segundos, então a movimentação pode atrasar um pouco.']] },
      { id: 'namefilter', q: 'O filtro de apelidos pega as pessoas erradas',
        a: ['Uma palavra é detectada em qualquer parte do apelido (sem diferenciar maiúsculas e minúsculas). Evite palavras muito curtas e adicione os grupos isentos em "Grupos excluídos". Comece com "cutucar" e mude para "expulsar" quando tiver certeza.'] },
      { id: 'support', q: 'O aviso de suporte não avisa ninguém',
        a: ['Se "IDs dos grupos da equipe" estiver vazio ou ninguém desses grupos estiver online, o usuário recebe a mensagem de "sem equipe". O mesmo usuário só é avisado de novo depois do tempo de espera (padrão 5 min).'] },
      { id: 'channelinfo', q: 'O nome do canal não muda',
        a: ['O bot precisa de permissão para editar o nome desse canal (um aviso "não foi possível alterar o nome do canal" aparece em Logs). Nomes de canal são limitados a 40 caracteres; modelos maiores são cortados. Como o nome muda, prefira selecionar o canal pelo ID.'] },
      { id: 'welcome', q: 'A mensagem de boas-vindas vai para todo mundo quando o bot inicia?',
        a: ['Não. Entradas nos primeiros 15 segundos após o bot se conectar (pessoas que já estavam online) são ignoradas, e o mesmo usuário não é cumprimentado de novo antes do tempo de "repetição".'] },
    ] },
    { section: 'Novos plugins', items: [
      { id: 'newplugins', q: 'O que os novos plugins fazem e de quais permissões precisam?',
        a: ['Todos são ativados por bot na página Plugins. "Diversão e ferramentas" vem ativado por padrão.', { table: [
            ['Plugin', 'O que faz', 'Comando', 'Permissão necessária para o bot'],
            ['Registro', 'Cutuca a equipe quando um usuário não registrado entra no canal de registro; o registro feito pela equipe adiciona o grupo de membro, remove o grupo de não registrado e move o usuário para o lobby', '`!register <name>` (somente grupos da equipe)', '`i_group_member_add_power`, `i_group_member_remove_power`, `i_client_move_power`, `i_client_poke_power`'],
            ['Criador de canais temporários', 'Cria um canal temporário com o nome de quem entra no canal criador e move o usuário para ele; o TeamSpeak o exclui quando fica vazio', '—', '`b_channel_create_temporary`, `i_client_move_power`'],
            ['Ranks de atividade', 'Conta o tempo passado no servidor e concede grupos nas horas definidas como `10=12`', '`!time`, `!top`', '`i_group_member_add_power` (e `..._remove_power` para remover o rank anterior)'],
            ['Guarda de canal', 'Move ou expulsa de canais protegidos os usuários sem um grupo permitido', '—', '`i_client_move_power` ou `i_client_kick_from_channel_power`'],
            ['Anti-flood', 'Cutuca quem envia muitas mensagens em pouco tempo e expulsa reincidentes do canal/servidor', '—', 'poderes de expulsão, `i_client_poke_power`'],
            ['Votar para pular', '`!next` não pula na hora; pula quando uma parte dos ouvintes votou (quem pediu a música e os grupos isentos pulam direto)', '`!next`', '—'],
            ['Modo DJ e limite da fila', 'Restringe a adição de músicas aos grupos de DJ e limita as músicas na fila por usuário; opcionalmente, pular/pausar/volume/parar só para DJs', '—', '—'],
            ['Mensagens agendadas', 'Envia mensagens em dias/horários definidos com linhas como `21:00 | message` ou `Sat,Sun 12:00 | message`', '—', 'mensagens no servidor: `b_client_server_textmessage_send`'],
            ['Diversão e ferramentas (ativado por padrão)', 'Dados, cara ou coroa, sorteio, enquetes, clima, câmbio, letras; desative os comandos que não quiser', '`!dice`, `!coin`, `!pick`, `!poll`, `!vote`, `!weather`, `!fx`, `!usd`, `!eur`, `!lyrics`', '—']] }] },
      { id: 'newcmds', q: 'Como uso os novos comandos?',
        a: [['`!register John` — registra John no canal de registro. Se vários usuários corresponderem, o bot lista todos; digite o nome completo.', '`!playlist save rock` (salva a fila) · `!playlist play rock` · `!playlist add rock` (adiciona a música atual) · `!playlist show rock` · `!playlist delete rock` · `!playlist` (todas as playlists). As playlists também aparecem na página Playlists do painel.', '`!poll What do we play tonight? | CS2 | LoL | Valorant` → todos digitam `!vote 2`; o resultado é publicado quando o tempo acaba (padrão: 2 min) ou com `!poll end`.', '`!weather istanbul` · `!fx EUR 50` · `!usd` · `!eur 20` · `!dice 2d6` · `!coin` · `!pick pizza | burger | sushi`', '`!lyrics` envia a letra da música atual por mensagem privada; `!lyrics never gonna give you up` busca outra música.', '`!stats` mostra as músicas mais tocadas e quem mais pediu nos últimos 30 dias; a página Estatística do painel mostra mais. `!time` mostra o seu próprio tempo e `!top`, os usuários mais ativos.']] },
      { id: 'ranks', q: 'Os ranks de atividade não contam o tempo / o !top está vazio',
        a: ['O plugin precisa estar ativado, e em apenas um bot (dois bots contariam o tempo em dobro). O tempo é somado uma vez por minuto. Escreva os ranks como `hours=groupID`, um por linha.'] },
      { id: 'tempchannel', q: 'O canal temporário não é criado',
        a: ['O bot precisa de permissão para criar canais temporários e mover clientes; a página Logs mostra o motivo ("could not create temporary channel"). Cada usuário recebe no máximo um canal a cada 30 segundos.'] },
      { id: 'services', q: 'Quais serviços são usados para clima, câmbio e letras?',
        a: ['Serviços gratuitos, sem chave de API: open-meteo.com (clima), open.er-api.com (câmbio), lrclib.net (letras). Só a cidade, o código da moeda ou o nome da música é enviado — nenhum dado de usuário. Os resultados ficam em cache por pouco tempo.'] },
    ] },
    { section: 'Comandos e idioma', items: [
      { id: 'rename', q: 'Posso renomear comandos como !play e !next?',
        a: ['Sim: Comandos → "Comandos internos". Digite um novo nome (ex.: `ara` → `play`) e salve. Desmarque "manter o nome antigo funcionando" para desativar o original. Os nomes dos comandos nas respostas, no texto de ajuda e no avatar são atualizados automaticamente.'] },
      { id: 'custom', q: 'Como adiciono meu próprio comando?',
        a: ['Comandos → "Comandos personalizados". Resposta em texto responde com um texto fixo (ex.: `!discord` → link de convite; `{user}`, `{args}`, `{time}`, `{date}` estão disponíveis). Atalho executa outro comando (ex.: `!song` → `!play`). Nomes personalizados não podem conflitar com comandos internos.'] },
      { id: 'avatar', q: 'Por que o avatar do bot mostra uma lista de comandos?',
        a: ['Quando ocioso, o avatar é gerado automaticamente a partir dos seus comandos (comandos renomeados, comandos personalizados e `!radio` se você tiver estações de rádio). Edite as descrições pelas linhas `avatar.*` em Comandos → "Textos do bot". Durante a reprodução, o avatar mostra a capa da música. Para usar sua própria imagem, coloque `sleep.png` em `bots/<bot-name>/avatars/`.'] },
      { id: 'lang', q: 'Quero que o bot responda em outro idioma',
        a: ['Ajustes → "Idioma das respostas no TeamSpeak": Türkçe, English, Deutsch, Español, Français, Русский, Português, Polski, Italiano. Respostas individuais podem ser editadas em Comandos → "Textos do bot". Para definir também os nomes dos comandos integrados de um idioma, use Comandos → "Usar nomes de comandos deste idioma" (a instalação faz isso automaticamente para o idioma escolhido; os nomes em turco sempre continuam funcionando).'] },
    ] },
    { section: 'Instalação', items: [
      { id: 'rights', q: '"You are missing the \'cmd.xxx\' right"',
        a: ['Adicione o comando à lista `"+" = [ ... ]` no topo do `rights.toml` na pasta do bot e reinicie. (Usuários do painel web não são afetados por este arquivo.)'] },
      { id: 'commander', q: 'O channel commander não ativa',
        a: ['O grupo de servidor do bot precisa da permissão `b_client_use_channel_commander`. Um aviso é registrado no log.'] },
      { id: 'connect', q: 'O bot não consegue se conectar',
        a: ['Use `ip:port` (porta padrão 9987) e defina a senha do servidor nos ajustes do bot, se necessário. Na primeira conexão, o servidor pode exigir um nível de segurança de identidade; o bot o calcula automaticamente (10-60 s). O log mostra o motivo.'] },
      { id: 'firewall', q: 'O painel não é acessível de fora',
        a: ['Libere a porta TCP 58913 no seu firewall (Firewall do Windows / `ufw allow 58913/tcp`) e nas regras de rede do seu provedor de nuvem. Se a primeira configuração for feita remotamente, é necessário um código de configuração (`KURULUM_KODU.txt`).'] },
      { id: 'forgot', q: 'Esqueci a senha de admin',
        a: ['Outro admin pode redefini-la na página Usuários. Se não houver mais nenhum admin, pare o bot, exclua o `frix.db` e inicie de novo (rádios, comandos personalizados e ajustes dos plugins são redefinidos; os bots e os ajustes do TeamSpeak são mantidos).'] },
      { id: 'linux', q: 'Sem som no Linux / erro "libopus"',
        a: ['`sudo apt install libopus0 ffmpeg` (Debian/Ubuntu). O `install.sh` os instala automaticamente. Se instalado em `/opt/frix`, verifique `systemctl status frix` e acompanhe os logs com `journalctl -u frix -f`.'] },
      { id: 'autostart', q: 'Iniciar automaticamente após reiniciar',
        a: ['Windows: ícone do `Frix.exe` na bandeja → "Iniciar com o Windows" (ativado por padrão). Linux: o `install.sh` ativa o serviço systemd (`systemctl enable frix`).'] },
    ] },
  ],
  pl: [
    { section: 'Ogólne', items: [
      { id: 'nosound', q: 'Utwór zostaje znaleziony, ale nie ma dźwięku / „Song queue ended” w logach',
        a: ['Sprawdź żółte/czerwone linie na stronie Logi. Zwykle to YouTube blokuje: Ustawienia → „Aktualizuj yt-dlp”; jeśli to nie pomoże, prześlij ciasteczka YouTube (poniżej). Jeśli bot nie jest połączony z TeamSpeak („łączenie”), dźwięk nie jest wysyłany.'] },
      { id: 'cookies', q: '„Sign in to confirm you\'re not a bot” w logach',
        a: ['YouTube blokuje IP serwera. Zainstaluj rozszerzenie przeglądarki `Get cookies.txt LOCALLY`, wyeksportuj `cookies.txt` dla youtube.com, będąc zalogowanym, i prześlij go w Ustawienia → Ciasteczka YouTube → „Prześlij cookies.txt”. Najlepiej użyj zapasowego konta Google.'] },
      { id: 'ytdlp', q: 'YouTube nagle przestał działać',
        a: ['YouTube często się zmienia. Ustawienia → „Aktualizuj yt-dlp”.'] },
      { id: 'dupname', q: 'Bot pojawia się jako „Frix1”',
        a: ['Na serwerze jest inny klient z tym samym nickiem (stary bot albo ponowne połączenie, zanim stara sesja wygasła). Zamknij tamtego klienta; bot odzyska nazwę przy następnym połączeniu.'] },
      { id: 'radio', q: 'Stacja radiowa nie gra',
        a: ['Użyj bezpośredniego adresu strumienia (`.mp3`, `.aac`, Icecast/Shoutcast) lub linku `.m3u`, `.pls`, `.m3u8`. Najpierw przetestuj go w VLC. Adresy stron internetowych nie działają.'] },
      { id: 'live', q: 'Czy bot odtwarza transmisje na żywo?',
        a: ['Tak: YouTube na żywo, Twitch i radio internetowe. Przewijanie nie jest dostępne dla transmisji na żywo (odtwarzacz pokazuje znacznik NA ŻYWO).'] },
      { id: 'roles', q: 'Co oznaczają role?',
        a: [['Admin: wszystko.', 'DJ: dodaje utwory/radia i steruje odtwarzaniem.', 'Widz: tylko odczyt.']] },
      { id: 'multibot', q: 'Jak uruchomić kilka botów?',
        a: ['Boty → „Nowy bot” — np. bot muzyczny i bot powitalny, który ma włączone tylko wtyczki powitania/ogłoszeń. Każdy bot łączy się jako osobny klient TeamSpeak.'] },
    ] },
    { section: 'Wtyczki', items: [
      { id: 'plugins', q: 'Jak konfigurować wtyczki i jakich uprawnień potrzebują?',
        a: ['Wtyczki włącza się osobno dla każdego bota: Wtyczki → wybierz bota → rozwiń kartę → skonfiguruj → Zapisz. Pola kanału przyjmują nazwę lub ID kanału (`5` lub `/5`). Pola grup przyjmują ID grup serwera oddzielone przecinkami (widoczne w TeamSpeak w Permissions → Server Groups).', { table: [
            ['Wtyczka', 'Co robi', 'Wymagane uprawnienie bota'],
            ['Wiadomość powitalna', 'Wiadomość prywatna, szturchnięcie lub wiadomość na kanale dla osób, które łączą się z serwerem / wchodzą na kanał bota', '— (szturchnięcie: `i_client_poke_power`)'],
            ['Ogłoszenia / reklamy', 'Publikuje wiadomości na kanale lub serwerze co określony czas (po kolei lub losowo)', 'Wiadomości serwerowe: `b_client_server_textmessage_send`'],
            ['Pauza, gdy sam', 'Wstrzymuje odtwarzanie, gdy na kanale bota nikogo nie ma, i wznawia, gdy ktoś wejdzie', '—'],
            ['Radio w bezczynności', 'Odtwarza wybraną stację, gdy kolejka jest pusta przez jakiś czas', '—'],
            ['Przenoszenie AFK', 'Przenosi bezczynnych, nieobecnych lub wyciszonych użytkowników na kanał AFK i z powrotem, gdy wrócą', '`i_client_move_power` (wyższe niż `i_client_needed_move_power` celu)'],
            ['Filtr nicków', 'Ostrzega lub wyrzuca użytkowników, których nick zawiera zakazane słowo', 'Wyrzucanie: `i_client_kick_from_server_power`'],
            ['Powiadomienia wsparcia', 'Szturcha dostępną obsługę, gdy ktoś wejdzie na kanał wsparcia, i informuje użytkownika', '`i_client_poke_power`'],
            ['Info w nazwie kanału', 'Aktualizuje nazwę kanału liczbą osób online i godziną', '`b_channel_modify_name` (na tym kanale)']] }] },
      { id: 'afk', q: 'Przenoszenie AFK nikogo nie przenosi',
        a: [['„Kanał AFK” musi dokładnie odpowiadać nazwie kanału (lub użyj jego ID). Jeśli kanał nie zostanie znaleziony, w Logach pojawi się ostrzeżenie „channel not found”.', 'Moc przenoszenia bota musi być wyższa niż użytkownika. Bot nie przeniesie adminów serwera; dodaj ich też do „Wykluczonych grup”.', 'Sprawdzanie odbywa się co 30 sekund, więc przeniesienie może się lekko opóźnić.']] },
      { id: 'namefilter', q: 'Filtr nicków łapie niewłaściwe osoby',
        a: ['Słowo jest dopasowywane w dowolnym miejscu nicku (bez względu na wielkość liter). Unikaj bardzo krótkich słów i dodaj zwolnione grupy do „Wykluczonych grup”. Zacznij od „szturchnięcia”, a na „wyrzucenie” przełącz, gdy będziesz pewien.'] },
      { id: 'support', q: 'Powiadomienia wsparcia nikogo nie powiadamiają',
        a: ['Jeśli pole „ID grup obsługi” jest puste lub nikt z tych grup nie jest online, użytkownik dostaje wiadomość o braku obsługi. Ten sam użytkownik nie zostanie ponownie zgłoszony przed upływem czasu odnowienia (domyślnie 5 min).'] },
      { id: 'channelinfo', q: 'Nazwa kanału się nie zmienia',
        a: ['Bot potrzebuje uprawnienia do edycji nazwy tego kanału (w Logach pojawia się ostrzeżenie „could not change channel name”). Nazwy kanałów mają limit 40 znaków; dłuższe szablony są obcinane. Ponieważ nazwa się zmienia, lepiej wybierać kanał po ID.'] },
      { id: 'welcome', q: 'Czy wiadomość powitalna trafia do wszystkich po uruchomieniu bota?',
        a: ['Nie. Wejścia w ciągu pierwszych 15 sekund po połączeniu bota (osoby, które już były online) są ignorowane, a ten sam użytkownik nie zostanie ponownie powitany przed upływem czasu „powtórzenia”.'] },
    ] },
    { section: 'Nowe wtyczki', items: [
      { id: 'newplugins', q: 'Co robią nowe wtyczki i jakich uprawnień potrzebują?',
        a: ['Wszystkie włącza się osobno dla każdego bota na stronie Wtyczki. „Rozrywka i narzędzia” jest domyślnie włączona.', { table: [
            ['Wtyczka', 'Co robi', 'Komenda', 'Wymagane uprawnienie bota'],
            ['Rejestracja', 'Szturcha obsługę, gdy niezarejestrowany użytkownik wejdzie na kanał rejestracji; rejestracja przez obsługę nadaje grupę członka, usuwa grupę niezarejestrowanych i przenosi użytkownika do lobby', '`!register <name>` (tylko grupy obsługi)', '`i_group_member_add_power`, `i_group_member_remove_power`, `i_client_move_power`, `i_client_poke_power`'],
            ['Kreator kanałów tymczasowych', 'Tworzy kanał tymczasowy nazwany od użytkownika, który wejdzie na kanał kreatora, i przenosi go tam; TeamSpeak usuwa kanał, gdy jest pusty', '—', '`b_channel_create_temporary`, `i_client_move_power`'],
            ['Rangi aktywności', 'Zlicza czas spędzony na serwerze i nadaje grupy po liczbie godzin zdefiniowanej np. `10=12`', '`!time`, `!top`', '`i_group_member_add_power` (oraz `..._remove_power`, aby usunąć poprzednią rangę)'],
            ['Ochrona kanałów', 'Przenosi lub wyrzuca z chronionych kanałów użytkowników bez dozwolonej grupy', '—', '`i_client_move_power` lub `i_client_kick_from_channel_power`'],
            ['Antyflood', 'Szturcha użytkowników wysyłających zbyt wiele wiadomości w krótkim czasie, a recydywistów wyrzuca z kanału/serwera', '—', 'uprawnienia do wyrzucania, `i_client_poke_power`'],
            ['Pomijanie głosowaniem', '`!next` nie pomija od razu; pomija, gdy zagłosuje określona część słuchaczy (zamawiający i grupy wyłączone pomijają bezpośrednio)', '`!next`', '—'],
            ['Tryb DJ i limit kolejki', 'Ogranicza dodawanie utworów do grup DJ i limituje liczbę utworów w kolejce na użytkownika; opcjonalnie pomijanie/pauza/głośność/stop tylko dla DJ-ów', '—', '—'],
            ['Zaplanowane wiadomości', 'Wysyła wiadomości w ustalone dni/godziny za pomocą linii takich jak `21:00 | message` lub `Sat,Sun 12:00 | message`', '—', 'Wiadomości serwerowe: `b_client_server_textmessage_send`'],
            ['Rozrywka i narzędzia (domyślnie włączona)', 'Kości, rzut monetą, losowy wybór, ankiety, pogoda, waluty, teksty piosenek; wyłącz komendy, których nie chcesz', '`!dice`, `!coin`, `!pick`, `!poll`, `!vote`, `!weather`, `!fx`, `!usd`, `!eur`, `!lyrics`', '—']] }] },
      { id: 'newcmds', q: 'Jak używać nowych komend?',
        a: [['`!register John` — rejestruje Johna na kanale rejestracji. Jeśli pasuje kilku użytkowników, bot ich wypisze; wpisz pełną nazwę.', '`!playlist save rock` (zapisz kolejkę) · `!playlist play rock` · `!playlist add rock` (dodaj bieżący utwór) · `!playlist show rock` · `!playlist delete rock` · `!playlist` (wszystkie playlisty). Playlisty widać też na stronie Playlisty w panelu.', '`!poll What do we play tonight? | CS2 | LoL | Valorant` → każdy wpisuje `!vote 2`; wynik pojawia się po upływie czasu (domyślnie 2 min) lub po `!poll end`.', '`!weather istanbul` · `!fx EUR 50` · `!usd` · `!eur 20` · `!dice 2d6` · `!coin` · `!pick pizza | burger | sushi`', '`!lyrics` wysyła tekst bieżącego utworu w wiadomości prywatnej; `!lyrics never gonna give you up` szuka innego utworu.', '`!stats` pokazuje najczęściej grane utwory i najczęściej zamawiających z ostatnich 30 dni; więcej pokazuje strona Statystyki w panelu. `!time` pokazuje twój czas, `!top` najaktywniejszych użytkowników.']] },
      { id: 'ranks', q: 'Rangi aktywności nie liczą czasu / !top jest puste',
        a: ['Wtyczka musi być włączona i to tylko na jednym bocie (dwa boty liczyłyby czas podwójnie). Czas jest dodawany co minutę. Rangi wpisuj jako `hours=groupID`, po jednej w linii.'] },
      { id: 'tempchannel', q: 'Kanał tymczasowy nie jest tworzony',
        a: ['Bot potrzebuje uprawnień do tworzenia kanałów tymczasowych i przenoszenia klientów; przyczynę pokazuje strona Logi („could not create temporary channel”). Użytkownik może dostać najwyżej jeden kanał co 30 sekund.'] },
      { id: 'services', q: 'Z jakich usług korzystają pogoda, waluty i teksty piosenek?',
        a: ['Darmowe usługi bez kluczy API: open-meteo.com (pogoda), open.er-api.com (waluty), lrclib.net (teksty). Wysyłane jest tylko miasto, kod waluty lub nazwa utworu — żadnych danych użytkowników. Wyniki są krótko przechowywane w pamięci podręcznej.'] },
    ] },
    { section: 'Komendy i język', items: [
      { id: 'rename', q: 'Czy mogę zmienić nazwy komend takich jak !play i !next?',
        a: ['Tak: Komendy → „Wbudowane komendy”. Wpisz nową nazwę (np. `ara` → `play`) i zapisz. Odznacz „zachowaj starą nazwę”, aby wyłączyć oryginał. Nazwy komend w odpowiedziach, tekście pomocy i awatarze aktualizują się automatycznie.'] },
      { id: 'custom', q: 'Jak dodać własną komendę?',
        a: ['Komendy → „Własne komendy”. Odpowiedź tekstowa odpowiada stałym tekstem (np. `!discord` → link z zaproszeniem; dostępne są `{user}`, `{args}`, `{time}`, `{date}`). Alias uruchamia inną komendę (np. `!song` → `!play`). Własne nazwy nie mogą kolidować z wbudowanymi komendami.'] },
      { id: 'avatar', q: 'Dlaczego awatar bota pokazuje listę komend?',
        a: ['W bezczynności awatar jest rysowany automatycznie na podstawie twoich komend (komendy o zmienionych nazwach, własne komendy oraz `!radio`, jeśli masz stacje radiowe). Opisy edytujesz w liniach `avatar.*` w Komendy → „Teksty bota”. Podczas odtwarzania awatar pokazuje okładkę utworu. Aby użyć własnego obrazu, umieść `sleep.png` w `bots/<bot-name>/avatars/`.'] },
      { id: 'lang', q: 'Chcę, żeby bot odpowiadał w innym języku',
        a: ['Ustawienia → „Język odpowiedzi w TeamSpeak”: Türkçe, English, Deutsch, Español, Français, Русский, Português, Polski, Italiano. Poszczególne odpowiedzi możesz edytować w Komendy → „Teksty bota”. Aby ustawić też nazwy wbudowanych komend dla danego języka, użyj Komendy → „Ustaw nazwy komend dla tego języka” (instalator robi to automatycznie dla wybranego języka; tureckie nazwy zawsze działają).'] },
    ] },
    { section: 'Instalacja', items: [
      { id: 'rights', q: '„You are missing the \'cmd.xxx\' right”',
        a: ['Dodaj komendę do górnej listy `"+" = [ ... ]` w pliku `rights.toml` w folderze bota i uruchom go ponownie. (Ten plik nie dotyczy użytkowników panelu WWW.)'] },
      { id: 'commander', q: 'Channel Commander się nie włącza',
        a: ['Grupa serwera bota potrzebuje uprawnienia `b_client_use_channel_commander`. W logach pojawi się ostrzeżenie.'] },
      { id: 'connect', q: 'Bot nie może się połączyć',
        a: ['Użyj formatu `ip:port` (domyślny port 9987) i w razie potrzeby ustaw hasło serwera w ustawieniach bota. Przy pierwszym połączeniu serwer może wymagać poziomu bezpieczeństwa tożsamości; bot oblicza go automatycznie (10-60 s). Przyczyna jest widoczna w logach.'] },
      { id: 'firewall', q: 'Panel nie jest dostępny z zewnątrz',
        a: ['Otwórz port TCP 58913 w zaporze (Zapora Windows / `ufw allow 58913/tcp`) i w regułach sieciowych dostawcy chmury. Jeśli pierwsza konfiguracja odbywa się zdalnie, wymagany jest kod konfiguracji (`KURULUM_KODU.txt`).'] },
      { id: 'forgot', q: 'Nie pamiętam hasła admina',
        a: ['Inny admin może je zresetować na stronie Użytkownicy. Jeśli nie ma już żadnego admina, zatrzymaj bota, usuń `frix.db` i uruchom go ponownie (radia, własne komendy i ustawienia wtyczek zostaną zresetowane; boty i ustawienia TeamSpeak zostaną zachowane).'] },
      { id: 'linux', q: 'Brak dźwięku na Linuksie / błąd „libopus”',
        a: ['`sudo apt install libopus0 ffmpeg` (Debian/Ubuntu). `install.sh` instaluje je automatycznie. Jeśli bot jest zainstalowany w `/opt/frix`, sprawdź `systemctl status frix` i śledź logi poleceniem `journalctl -u frix -f`.'] },
      { id: 'autostart', q: 'Automatyczne uruchamianie po restarcie',
        a: ['Windows: ikona `Frix.exe` w zasobniku → „Start with Windows” (domyślnie włączone). Linux: `install.sh` włącza usługę systemd (`systemctl enable frix`).'] },
    ] },
  ],
  it: [
    { section: 'Generale', items: [
      { id: 'nosound', q: 'Il brano viene trovato ma non si sente nulla / "Song queue ended" nel log',
        a: ['Controlla le righe gialle/rosse nella pagina Log. Di solito è YouTube che blocca: Impostazioni → "Aggiorna yt-dlp"; se non basta, carica i cookie di YouTube (vedi sotto). Se il bot non è connesso a TeamSpeak ("connessione"), non viene inviato alcun audio.'] },
      { id: 'cookies', q: '"Sign in to confirm you\'re not a bot" nel log',
        a: ['YouTube blocca l\'IP del server. Installa l\'estensione del browser `Get cookies.txt LOCALLY`, esporta `cookies.txt` per youtube.com mentre hai effettuato l\'accesso e caricalo in Impostazioni → Cookie di YouTube → "Carica cookies.txt". Meglio usare un account Google secondario.'] },
      { id: 'ytdlp', q: 'YouTube ha smesso di funzionare all\'improvviso',
        a: ['YouTube cambia spesso. Impostazioni → "Aggiorna yt-dlp".'] },
      { id: 'dupname', q: 'Il bot appare come "Frix1"',
        a: ['Sul server c\'è un altro client con lo stesso nickname (un vecchio bot, o una riconnessione prima che la vecchia sessione scadesse). Chiudi l\'altro: il bot riprende il suo nome alla connessione successiva.'] },
      { id: 'radio', q: 'Una stazione radio non parte',
        a: ['Usa un URL di stream diretto (`.mp3`, `.aac`, Icecast/Shoutcast) o un link `.m3u`, `.pls`, `.m3u8`. Provalo prima in VLC. Gli URL di pagine web non funzionano.'] },
      { id: 'live', q: 'Può riprodurre stream in diretta?',
        a: ['Sì: YouTube live, Twitch e radio online. Negli stream in diretta non puoi spostarti nel brano (il player mostra l\'etichetta LIVE).'] },
      { id: 'roles', q: 'Cosa significano i ruoli?',
        a: [['Admin: tutto.', 'DJ: aggiunge brani/radio e controlla la riproduzione.', 'Spettatore: sola lettura.']] },
      { id: 'multibot', q: 'Come faccio a usare più bot?',
        a: ['Bot → "Nuovo bot" — es. un bot musicale più un bot di benvenuto con attivi solo i plugin di benvenuto/annunci. Ogni bot si connette come un client TeamSpeak a sé.'] },
    ] },
    { section: 'Plugin', items: [
      { id: 'plugins', q: 'Come si configurano i plugin e quali permessi servono?',
        a: ['I plugin si attivano per ogni bot: Plugin → scegli un bot → espandi la scheda → configura → Salva. I campi canale accettano il nome o l\'ID del canale (`5` o `/5`). I campi gruppo accettano ID di gruppi server separati da virgola (visibili in TeamSpeak sotto Permissions → Server Groups).', { table: [
            ['Plugin', 'Cosa fa', 'Permesso necessario al bot'],
            ['Messaggio di benvenuto', 'Messaggio privato, poke o messaggio nel canale per chi si connette / entra nel canale del bot', '— (poke: `i_client_poke_power`)'],
            ['Annunci / Pubblicità', 'Pubblica messaggi nel canale o nel server a intervalli (in ordine o casuali)', 'Messaggi server: `b_client_server_textmessage_send`'],
            ['Pausa quando è solo', 'Mette in pausa quando nel canale del bot non resta nessuno, riprende quando entra qualcuno', '—'],
            ['Radio di attesa', 'Riproduce una stazione radio scelta quando la coda è vuota da un po\'', '—'],
            ['Spostamento AFK', 'Sposta gli utenti inattivi, assenti o con l\'audio disattivato in un canale AFK e li riporta indietro quando tornano', '`i_client_move_power` (maggiore di `i_client_needed_move_power` dell\'utente)'],
            ['Filtro nickname', 'Avvisa o espelle gli utenti il cui nickname contiene una parola vietata', 'Kick: `i_client_kick_from_server_power`'],
            ['Avviso supporto', 'Fa il poke allo staff online quando qualcuno entra nel canale di supporto e informa l\'utente', '`i_client_poke_power`'],
            ['Info nel nome canale', 'Mantiene aggiornato il nome di un canale con il numero di utenti online e l\'ora', '`b_channel_modify_name` (su quel canale)']] }] },
      { id: 'afk', q: 'Lo spostamento AFK non sposta nessuno',
        a: [['Il "canale AFK" deve corrispondere esattamente al nome del canale (oppure usa il suo ID). Se non viene trovato, nei Log compare l\'avviso "canale non trovato".', 'Il potere di spostamento del bot deve essere maggiore di quello dell\'utente. Non può spostare gli admin del server; aggiungili anche a "Gruppi esclusi".', 'Il controllo avviene ogni 30 secondi, quindi uno spostamento può avere un leggero ritardo.']] },
      { id: 'namefilter', q: 'Il filtro nickname colpisce le persone sbagliate',
        a: ['Una parola viene trovata in qualsiasi punto del nickname (senza distinzione tra maiuscole e minuscole). Evita parole molto corte e aggiungi i gruppi esenti a "Gruppi esclusi". Inizia con "poke" e passa a "kick" quando sei sicuro.'] },
      { id: 'support', q: 'L\'avviso supporto non avvisa nessuno',
        a: ['Se "ID gruppi staff" è vuoto o nessuno di quei gruppi è online, l\'utente riceve il messaggio "nessuno staff". Lo stesso utente non viene segnalato di nuovo finché non è trascorso il tempo di attesa (predefinito 5 min).'] },
      { id: 'channelinfo', q: 'Il nome del canale non cambia',
        a: ['Il bot deve avere il permesso di modificare il nome di quel canale (nei Log compare l\'avviso "impossibile cambiare il nome del canale"). I nomi dei canali sono limitati a 40 caratteri; i modelli più lunghi vengono troncati. Dato che il nome cambia, è meglio selezionare il canale tramite ID.'] },
      { id: 'welcome', q: 'Il messaggio di benvenuto arriva a tutti quando il bot si avvia?',
        a: ['No. Gli ingressi nei primi 15 secondi dopo la connessione del bot (persone già online) vengono ignorati, e lo stesso utente non viene salutato di nuovo prima del tempo di "ripetizione".'] },
    ] },
    { section: 'Nuovi plugin', items: [
      { id: 'newplugins', q: 'Cosa fanno i nuovi plugin e quali permessi servono?',
        a: ['Si attivano tutti per ogni bot nella pagina Plugin. "Svago e strumenti" è attivo di default.', { table: [
            ['Plugin', 'Cosa fa', 'Comando', 'Permesso necessario al bot'],
            ['Registrazione', 'Fa il poke allo staff quando un utente non registrato entra nel canale di registrazione; la registrazione da parte dello staff assegna il gruppo membri, rimuove il gruppo non registrati e sposta l\'utente nella lobby', '`!register <name>` (solo gruppi staff)', '`i_group_member_add_power`, `i_group_member_remove_power`, `i_client_move_power`, `i_client_poke_power`'],
            ['Creatore di canali temporanei', 'Crea un canale temporaneo con il nome dell\'utente che entra nel canale creatore e ve lo sposta; TeamSpeak lo elimina quando è vuoto', '—', '`b_channel_create_temporary`, `i_client_move_power`'],
            ['Ranghi attività', 'Conta il tempo trascorso sul server e assegna gruppi alle ore definite come `10=12`', '`!time`, `!top`', '`i_group_member_add_power` (e `..._remove_power` per rimuovere il rango precedente)'],
            ['Guardia canali', 'Sposta o espelle dai canali protetti gli utenti senza un gruppo consentito', '—', '`i_client_move_power` o `i_client_kick_from_channel_power`'],
            ['Anti-flood', 'Fa il poke a chi invia troppi messaggi in poco tempo ed espelle i recidivi dal canale/server', '—', 'Permessi di kick, `i_client_poke_power`'],
            ['Voto per saltare', '`!next` non salta subito: salta quando una parte degli ascoltatori ha votato (chi ha richiesto il brano e i gruppi esenti saltano direttamente)', '`!next`', '—'],
            ['Modalità DJ e limite coda', 'Limita l\'aggiunta di brani ai gruppi DJ e il numero di brani in coda per utente; opzionalmente salta/pausa/volume/stop solo per i DJ', '—', '—'],
            ['Messaggi programmati', 'Invia messaggi in giorni/orari stabiliti con righe come `21:00 | message` o `Sat,Sun 12:00 | message`', '—', 'Messaggi server: `b_client_server_textmessage_send`'],
            ['Svago e strumenti (attivo di default)', 'Dadi, testa o croce, scelta casuale, sondaggi, meteo, valute, testi; disattiva i comandi che non vuoi', '`!dice`, `!coin`, `!pick`, `!poll`, `!vote`, `!weather`, `!fx`, `!usd`, `!eur`, `!lyrics`', '—']] }] },
      { id: 'newcmds', q: 'Come si usano i nuovi comandi?',
        a: [['`!register John` — registra John nel canale di registrazione. Se più utenti corrispondono, il bot li elenca: scrivi il nome completo.', '`!playlist save rock` (salva la coda) · `!playlist play rock` · `!playlist add rock` (aggiunge il brano attuale) · `!playlist show rock` · `!playlist delete rock` · `!playlist` (tutte le playlist). Le playlist compaiono anche nella pagina Playlist del pannello.', '`!poll What do we play tonight? | CS2 | LoL | Valorant` → tutti scrivono `!vote 2`; il risultato viene pubblicato allo scadere del tempo (di default 2 min) o con `!poll end`.', '`!weather istanbul` · `!fx EUR 50` · `!usd` · `!eur 20` · `!dice 2d6` · `!coin` · `!pick pizza | burger | sushi`', '`!lyrics` invia il testo del brano attuale in messaggio privato; `!lyrics never gonna give you up` cerca un altro brano.', '`!stats` mostra i brani più riprodotti e i top richiedenti degli ultimi 30 giorni; la pagina Statistiche del pannello mostra di più. `!time` mostra il tuo tempo, `!top` gli utenti più attivi.']] },
      { id: 'ranks', q: 'I ranghi attività non contano il tempo / !top è vuoto',
        a: ['Il plugin deve essere attivo, e su un solo bot (con due bot il tempo verrebbe contato due volte). Il tempo viene aggiunto una volta al minuto. Scrivi i ranghi come `hours=groupID`, uno per riga.'] },
      { id: 'tempchannel', q: 'Il canale temporaneo non viene creato',
        a: ['Il bot deve avere il permesso di creare canali temporanei e spostare i client; la pagina Log mostra il motivo ("could not create temporary channel"). Un utente può ottenere al massimo un canale ogni 30 secondi.'] },
      { id: 'services', q: 'Quali servizi usano meteo, valute e testi?',
        a: ['Servizi gratuiti senza chiavi API: open-meteo.com (meteo), open.er-api.com (valute), lrclib.net (testi). Viene inviato solo il nome della città, il codice valuta o il nome del brano — nessun dato utente. I risultati vengono memorizzati per poco tempo.'] },
    ] },
    { section: 'Comandi e lingua', items: [
      { id: 'rename', q: 'Posso rinominare comandi come !play e !next?',
        a: ['Sì: Comandi → "Comandi integrati". Inserisci un nuovo nome (es. `ara` → `play`) e salva. Togli la spunta a "mantieni attivo il vecchio nome" per disattivare l\'originale. I nomi dei comandi nelle risposte, nel testo di aiuto e nell\'avatar si aggiornano automaticamente.'] },
      { id: 'custom', q: 'Come aggiungo un mio comando?',
        a: ['Comandi → "Comandi personalizzati". Risposta testuale risponde con un testo fisso (es. `!discord` → link di invito; sono disponibili `{user}`, `{args}`, `{time}`, `{date}`). Alias esegue un altro comando (es. `!song` → `!play`). I nomi personalizzati non possono coincidere con i comandi integrati.'] },
      { id: 'avatar', q: 'Perché l\'avatar del bot mostra un elenco di comandi?',
        a: ['Quando è inattivo, l\'avatar viene disegnato automaticamente a partire dai tuoi comandi (comandi rinominati, comandi personalizzati e `!radio` se hai stazioni radio). Modifica le descrizioni tramite le righe `avatar.*` in Comandi → "Testi del bot". Durante la riproduzione, l\'avatar mostra la copertina del brano. Per usare una tua immagine, metti `sleep.png` in `bots/<bot-name>/avatars/`.'] },
      { id: 'lang', q: 'Voglio che il bot risponda in un\'altra lingua',
        a: ['Opzioni → "Lingua delle risposte su TeamSpeak": Türkçe, English, Deutsch, Español, Français, Русский, Português, Polski, Italiano. Le singole risposte si modificano in Comandi → "Testi del bot". Per impostare anche i nomi dei comandi integrati per una lingua, usa Comandi → "Usa i nomi dei comandi di questa lingua" (la configurazione iniziale lo fa automaticamente per la lingua scelta; i nomi turchi funzionano sempre).'] },
    ] },
    { section: 'Installazione', items: [
      { id: 'rights', q: '"You are missing the \'cmd.xxx\' right"',
        a: ['Aggiungi il comando alla lista `"+" = [ ... ]` in cima a `rights.toml` nella cartella del bot e riavvia. (Questo file non riguarda gli utenti del pannello web.)'] },
      { id: 'commander', q: 'Il channel commander non si attiva',
        a: ['Il gruppo server del bot ha bisogno del permesso `b_client_use_channel_commander`. Viene registrato un avviso nel log.'] },
      { id: 'connect', q: 'Il bot non riesce a connettersi',
        a: ['Usa `ip:port` (porta predefinita 9987) e, se serve, imposta la password del server nelle impostazioni del bot. Alla prima connessione il server può richiedere un livello di sicurezza dell\'identità; il bot lo calcola automaticamente (10-60 s). Il log mostra il motivo.'] },
      { id: 'firewall', q: 'Il pannello non è raggiungibile dall\'esterno',
        a: ['Apri la porta TCP 58913 nel firewall (Windows Firewall / `ufw allow 58913/tcp`) e nelle regole di rete del tuo provider cloud. Se la prima configurazione avviene da remoto, serve un codice di configurazione (`KURULUM_KODU.txt`).'] },
      { id: 'forgot', q: 'Ho dimenticato la password dell\'admin',
        a: ['Un altro admin può reimpostarla nella pagina Utenti. Se non resta nessun admin, ferma il bot, elimina `frix.db` e riavvialo (radio, comandi personalizzati e impostazioni dei plugin vengono azzerati; bot e impostazioni di TeamSpeak restano).'] },
      { id: 'linux', q: 'Nessun suono su Linux / errore "libopus"',
        a: ['`sudo apt install libopus0 ffmpeg` (Debian/Ubuntu). `install.sh` li installa automaticamente. Se installato in `/opt/frix`, controlla `systemctl status frix` e segui i log con `journalctl -u frix -f`.'] },
      { id: 'autostart', q: 'Avvio automatico dopo il riavvio',
        a: ['Windows: icona di `Frix.exe` nella tray → "Start with Windows" (attivo di default). Linux: `install.sh` abilita il servizio systemd (`systemctl enable frix`).'] },
    ] },
  ],
};
